return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'el','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-29T14:57:34+00:00','po-revision-date'=>'2026-07-05 20:52+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Πολυγλωσσική δρομολόγηση, πλήρης πολυγλωσσική SEO (hreflang, Open Graph, Schema.org, sitemap), και εργαλεία AI για περιεχόμενο για το WordPress. Ανίχνευση γλώσσας, δρομολόγηση URL, μετάφραση, δημιουργία περιεχομένου και πλήρης στρώση SEO — χωρίς ανάγκη για συμπληρωματικό πρόσθετο.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Μετάφραση','Lingua Forge — Quick Translate'=>'Lingua Forge — Γρήγορη Μετάφραση','Informative'=>'Ενημερωτικό','Persuasive'=>'Πειστικό','Storytelling'=>'Αφήγηση','Technical'=>'Τεχνικό','Conversational'=>'Διαλογικό','Translate missing'=>'Αποτυχία μετάφρασης','%d comment translation created.'=>'%d μετάφραση σχόλιου δημιουργήθηκε.' . "\0" . '%d μεταφράσεις σχόλιων δημιουργήθηκαν.','%d pair could not be translated yet (e.g. a nested reply waiting on its parent, or a language currently in cooldown after repeated failures).'=>'%d ζεύγος δεν έχει μεταφραστεί ακόμη (π.χ. μία εσωτερική απάντηση που περιμένει τον γονέα της ή μία γλώσσα που είναι προσωρινά απενεργοποιημένη μετά από επαναλαμβανόμενες αποτυχίες).' . "\0" . '%d ζεύγη δεν έχουν μεταφραστεί ακόμη (π.χ. εσωτερικές απαντήσεις που περιμένουν τον γονέα τους ή μία γλώσσα που είναι προσωρινά απενεργοποιημένη μετά από επαναλαμβανόμενες αποτυχίες).','Permission denied.'=>'Άρνηση άδειας πρόσβασης.','Cannot determine target language from slug.'=>'Αδύνατη η προσδιορισμός της στόχου γλώσσας από το slug.','Invalid post type.'=>'Μη έγκυρος τύπος ανάρτησης.','Invalid or primary language.'=>'Μη έγκυρη ή κύρια γλώσσα.','Template not found or not stored in the database.'=>'Το πρότυπο δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template has no content.'=>'Το πρότυπο δεν έχει περιεχόμενο.','No internal links found to update.'=>'Δεν βρέθηκαν εσωτερικοί σύνδεσμοι για ενημέρωση.','%d link updated.'=>'%d σύνδεσμος ενημερώθηκε.' . "\0" . '%d σύνδεσμοι ενημερώθηκαν.','No language-specific template parts found to map.'=>'Δεν βρέθηκαν τμήματα προτύπου που να χρειάζονται χαρτογράφηση.','No template part references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών τμήματος προτύπου.','%d part reference updated.'=>'Ενημερώθηκε %d αναφορά τμήματος.' . "\0" . 'Ενημερώθηκαν %d αναφορές τμήματος.','Invalid language.'=>'Μη έγκυρη γλώσσα.','Template part not found or not stored in the database.'=>'Το τμήμα προτύπου δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template part has no content.'=>'Το τμήμα προτύπου δεν έχει περιεχόμενο.','No navigation references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών πλοήγησης.','%d navigation reference updated.'=>'Ενημερώθηκε %d αναφορά πλοήγησης.' . "\0" . 'Ενημερώθηκαν %d αναφορές πλοήγησης.','No AI provider configured.'=>'Δεν έχει διαμορφωθεί πάροχος AI.','Missing pattern name or language.'=>'Λείπει όνομα μοτίβου ή γλώσσα.','Pattern not found.'=>'Το μοτίβο δεν βρέθηκε.','Pattern has no content to translate.'=>'Το μοτίβο δεν έχει περιεχόμενο για μετάφραση.','AI provider returned an empty response.'=>'Ο πάροχος AI επέστρεψε κενή απάντηση.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Το μοτίβο μεταφράστηκε και αποθηκεύτηκε. Αντιγράψτε το περιεχόμενο στη δημοσίευση CPT μέσω του επεξεργαστή μπλοκ ή χρησιμοποιήστε το ως σημείο εκκίνησης για ένα Επαναχρησιμοποιήσιμο Μπλοκ.','%d template repaired.'=>'%d πρότυπο επισκευάστηκε.' . "\0" . '%d πρότυπα επισκευάστηκαν.','All template metadata is already up to date.'=>'Όλα τα μεταδεδομένα προτύπου είναι ήδη ενημερωμένα.','Invalid template type.'=>'Μη έγκυρος τύπος προτύπου.','Template "%s" already exists.'=>'Το πρότυπο "%s" υπάρχει ήδη.','Fix Links'=>'Επιδιόρθωση Συνδέσμων','Fix Parts'=>'Επιδιόρθωση Μερών','Re-create'=>'Ανασύσταση','"%s" recreated.'=>'"%s" ανασυντάχθηκε.','"%s" created.'=>'"%s" δημιουργήθηκε.','Invalid template part.'=>'Μη έγκυρο τμήμα προτύπου.','Template part "%s" already exists.'=>'Το τμήμα προτύπου "%s" υπάρχει ήδη.','Fix Nav'=>'Επιδιόρθωση Πλοήγησης','"%1$s" recreated. %2$d template updated.'=>'"%1$s" ανασυντάχθηκε. %2$d πρότυπο ενημερώθηκε.' . "\0" . '"%1$s" ανασυντάχθηκε. %2$d πρότυπα ενημερώθηκαν.','"%1$s" created. %2$d template updated.'=>'"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.' . "\0" . '"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.','Page'=>'Σελίδα','Single'=>'Μοναδικό','Search'=>'Αναζήτηση','Search Results'=>'Αποτελέσματα Αναζήτησης','Archive'=>'Αρχείο','Front Page'=>'Αρχική Σελίδα','Blog Home'=>'Αρχική σελίδα ιστολογίου','Single: %s'=>'Μονό: %s','Single %s'=>'Μονό %s','Archive: %s'=>'Αρχείο: %s','%s Archive'=>'%s Αρχείο','No source content found to translate.'=>'Δεν βρέθηκε περιεχόμενο πηγής για μετάφραση.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Μεταφράστηκε. Ανασκόπηση στον Επεξεργαστή Ιστότοπου — οι εσωτερικοί σύνδεσμοι, οι διευθύνσεις URL πλοήγησης και τα ονόματα προτύπων δεν ενημερώνονται αυτόματα.','Navigation not found.'=>'Δεν βρέθηκε πλοήγηση.','Navigation has no content to translate.'=>'Η πλοήγηση δεν έχει περιεχόμενο για μετάφραση.','"%1$s %2$s" saved.'=>'"%1$s %2$s" αποθηκεύτηκε.','SEO Analysis'=>'Ανάλυση SEO','Profile'=>'Προφίλ','Details ↗'=>'Λεπτομέρειες ↗','/ 100'=>'/ 100','Overall SEO score'=>'Συνολική βαθμολογία SEO','Metric'=>'Μέτρο','Finding'=>'Εύρεση','Title'=>'Τίτλος','Meta description'=>'Μετα-περιγραφή','Word count'=>'Αριθμός λέξεων','Reading time'=>'Χρόνος ανάγνωσης','Headings'=>'Επικεφαλίδες','Images'=>'Εικόνες','Links'=>'Σύνδεσμοι','AI Recommendations'=>'Συστάσεις AI','Run AI Analysis'=>'Εκτέλεση ανάλυσης AI','Analyzing…'=>'Ανάλυση σε εξέλιξη…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Διαμορφώστε έναν πάροχο AI στις Ρυθμίσεις → Κλειδιά API για ενεργοποίηση συστάσεων με AI.','AI analysis failed. Please try again.'=>'Αποτυχία ανάλυσης AI. Παρακαλώ δοκιμάστε ξανά.','Suggested title'=>'Προτεινόμενος τίτλος','Suggested meta description'=>'Προτεινόμενη μετα-περιγραφή','Loaded from cache.'=>'Φορτώθηκε από την cache.','↺ Refresh AI Analysis'=>'↺ Ανανεώστε την ανάλυση AI','Analyse…'=>'Ανάλυση…','Analysis request failed. Please try again.'=>'Αποτυχία αιτήματος ανάλυσης. Παρακαλώ δοκιμάστε ξανά.','No translation found — analyzed the source language version.'=>'Δεν βρέθηκε μετάφραση — αναλύθηκε η έκδοση της πηγής γλώσσας.','Translate page…'=>'Μετάφραση σελίδας…','Generate content…'=>'Δημιουργία περιεχομένου…','AI Behaviour Preset'=>'Προκαθορισμένο AI Συμπεριφοράς','Custom'=>'Προσαρμοσμένο','Global default (%s)'=>'Παγκόσμια προεπιλογή (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Οι προσαρμοσμένες οδηγίες προτροπής σε όλο τον ιστότοπο (Ρυθμίσεις → Συμπεριφορά) προστίθενται πάντα σε κάθε αίτημα, ανεξάρτητα από αυτήν την επιλογή.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Όλες οι άλλες λειτουργίες πάντα χρησιμοποιούν την παγκόσμια προεπιλογή.','Close'=>'Κλείσιμο','From'=>'Από','Retranslate'=>'Επαναμετάφραση','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Μεταφράστε ξανά κάθε άλλη έκδοση γλώσσας από αυτήν την ανάρτηση. Δημιουργεί όλες που λείπουν και αντικαθιστά όλες που υπάρχουν ήδη — συμπεριλαμβανομένης της κύριας γλώσσας, εάν αυτή η ανάρτηση είναι μετάφραση.','Sync'=>'Συγχρονισμός','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Αναθέστε το σωστό πρότυπο ειδικό για κάθε γλώσσα σε κάθε υπάρχουσα μετάφραση αυτής της ανάρτησης. Χωρίς κλήση AI και χωρίς αλλαγές περιεχομένου — δωρεάν και ασφαλές για εκτέλεση ανά πάσα στιγμή.','Template Sync — reassign templates for every translation'=>'Συγχρονισμός προτύπου — αναθέστε πρότυπα για κάθε μετάφραση','TS'=>'ΣΠ','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Τελευταία βαθμολογία SEO βάσει κανόνων. Εκτελέστε ανάλυση στις Ρυθμίσεις → SEO → Ανάλυση για ενημέρωση.','Translating…'=>'Μεταφράζοντας…','Retranslating…'=>'Επαναμεταφράζοντας…','Syncing…'=>'Συγχρονισμός…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Αυτό μεταφράζει ξανά κάθε άλλη έκδοση γλώσσας αυτής της ανάρτησης από αυτήν — δημιουργώντας όλες που λείπουν και αντικαθιστώντας όλες που υπάρχουν ήδη (συμπεριλαμβανομένης της κύριας γλώσσας, εάν αυτή η ανάρτηση είναι μετάφραση). Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','Syncing templates…'=>'Συγχρονισμός προτύπων…','✓ Done'=>'✓ Ολοκληρώθηκε','Error'=>'Σφάλμα','Navigation posts are translated via the Router tab, not this button.'=>'Οι δημοσιεύσεις πλοήγησης μεταφράζονται μέσω της καρτέλας Router, όχι με αυτό το κουμπί.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Η δημιουργία μεταφράσεων για τον τύπο δημοσίευσης "%s" απαιτεί ενεργή ενσωμάτωση. Παρακαλώ βεβαιωθείτε ότι η απαιτούμενη ενσωμάτωση είναι εγκατεστημένη και ενεργή.','No %s version found in this translation group.'=>'Δεν βρέθηκε έκδοση %s σε αυτήν την ομάδα μεταφράσεων.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Ο συγχρονισμός από ένα προϊόν WooCommerce δευτερεύουσας γλώσσας είναι απενεργοποιημένος προεπιλογή, καθώς θα αντικαθιστούσε το κύριο προϊόν. Ενεργοποιήστε το στο Ρυθμίσεις → Συμπεριφορά → WooCommerce εάν θέλετε μια μετάφραση να μπορεί να γίνει το νέο περιεχόμενο πηγής.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Ο συγχρονισμός από μια ανάρτηση δευτερεύουσας γλώσσας είναι απενεργοποιημένος προεπιλογή, καθώς θα αντικαθιστούσε την κύρια ανάρτηση. Ενεργοποιήστε το στο Ρυθμίσεις → Συμπεριφορά → Συγχρονισμός εάν θέλετε μια μετάφραση να μπορεί να γίνει το νέο περιεχόμενο πηγής.','Skipped — you do not have permission to edit the existing translation.'=>'Παραλείφθηκε — δεν έχετε δικαίωμα να επεξεργαστείτε την υπάρχουσα μετάφραση.','Creating translations for post type "%s" requires an active integration.'=>'Η δημιουργία μεταφράσεων για τον τύπο ανάρτησης "%s" απαιτεί ενεργή ολοκλήρωση.','Template Sync can only be run from the primary/source-language post.'=>'Ο συγχρονισμός προτύπου μπορεί να εκτελεστεί μόνο από την ανάρτηση κύριας/πηγής γλώσσας.','Skipped — you do not have permission to edit this translation.'=>'Παραλείφθηκε — δεν έχετε δικαίωμα να επεξεργαστείτε αυτήν τη μετάφραση.','Translation Caching'=>'Αποθήκευση cache μεταφράσεων','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Το Lingua Forge χρησιμοποιεί δύο ανεξάρτητα επίπεδα cache για να αποφύγει περιττές κλήσεις API AI. Χρησιμοποιήστε τις καρτέλες παρακάτω για να επιθεωρήσετε και να διαχειριστείτε κάθε ένα.','API Response Cache'=>'Cache Απαντήσεων API','Translation Memory'=>'Μνήμη Μετάφρασης','(disabled)'=>'(απενεργοποιημένο)','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Μνήμη cache ανά ανάρτηση για μεταφράσεις που παράγονται από AI, μετα-περιγραφές, αποσπάσματα και περιεχόμενο. Οι καταχωρίσεις ακυρώνονται αυτόματα όταν αλλάζει το περιεχόμενο ή ο πάροχος/μοντέλο AI.','Enable API response caching'=>'Ενεργοποίηση cache απαντήσεων API','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Η Κρυφή μνήμη απόκρισης API αποθηκεύει το ακατέργαστο αποτέλεσμα κάθε αίτησης AI — μετάφραση, μετα-περιγραφή, απόσπασμα και δημιουργία περιεχομένου — με κλειδί έναν hash των εισόδων (περιεχόμενο, ζεύγος γλωσσών, πάροχος, μοντέλο). Απενεργοποιήστε κατά τη ρύθμιση προτροπής ή όταν χρειάζεστε κάθε αίτηση να φτάνει στον πάροχο AI. Η απενεργοποίηση δεν διαγράφει τις αποθηκευμένες καταχωρίσεις — η ενεργοποίηση τις επαναφέρει.','Save'=>'Αποθήκευση','Cached API responses'=>'Αποθηκευμένες απαντήσεις API','API calls saved by cache'=>'Κλήσεις API αποθηκευμένες από την cache','(avg %.1f hits/entry)'=>'(μέσο όρο %.1f χτυπήματα/καταχώριση)','Oldest cached response'=>'Παλαιότερη αποθηκευμένη απάντηση','Most recent cached response'=>'Πιο πρόσφατη αποθηκευμένη απάντηση','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Εκκαθάριση όλων των αποθηκευμένων αποτελεσμάτων ΤΝ; Οι μελλοντικά αιτήματα θα ενεργοποιούν νέες κλήσεις API μέχρι να ξαναχτιστεί η προσωρινή μνήμη.','Clear API Response Cache'=>'Εκκαθάριση Cache Απαντήσεων API','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Κοινόχρηστη μνήμη cache μετάφρασης σε επίπεδο μπλοκ. Όταν ενεργοποιείται, τα ίδια μπλοκ (ίδια μορφοποίηση, ζεύγος γλώσσας και γλωσσάρι) σερβίρονται από τη μνήμη αντί να καλούν ξανά την AI. Οι επεξεργασίες γλωσσάρι και οι αλλαγές προεπιλογής Συμμόρφωσης ακυρώνουν αυτόματα τις επηρεαζόμενες αποθηκευμένες μεταφράσεις.','Enable block-level translation cache reuse across posts'=>'Ενεργοποίηση επανάχρησης cache μεταφράσεων σε επίπεδο μπλοκ σε δημοσιεύματα','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Αυτή τη στιγμή παραλείπεται για δημοσιεύματα που χρησιμοποιούν εικονίδια θέματος μπλοκ-comment (wp:details πεδία περίληψης, κ.λπ.) — αυτά περνούν στη υπάρχουσα διαδρομή μετάφρασης με μία κλήση.','Cached block translations'=>'Αποθηκευμένες μεταφράσεις μπλοκ','Block translation reuses'=>'Χρήση επαναχρησιμοποίησης μετάφρασης μπλοκ','(avg %.1f hits/block)'=>'(μέσος όρος %.1f επιτυχίες/μπλοκ)','Oldest cached block'=>'Παλαιότερο αποθηκευμένο μπλοκ','Most recent cached block'=>'Πιο πρόσφατο αποθηκευμένο μπλοκ','Approximate size'=>'Περίπου μέγεθος','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Εκκαθάριση ολόκληρης της μνήμης μετάφρασης; Οι μελλοντικές μεταφράσεις θα ξαναχτίσουν την cache καθώς εκτελούνται.','Clear Translation Memory'=>'Εκκαθάριση μνήμης μετάφρασης','API Response Cache setting saved.'=>'Αποθηκεύτηκε η ρύθμιση Cache Απόκρισης API.','Translation Memory setting saved.'=>'Η ρύθμιση Μνήμης Μεταφράσεων αποθηκεύτηκε.','AI cache cleared. %d entry was removed.'=>'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχώριση αφαιρέθηκε.' . "\0" . 'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχωρίσεις αφαιρέθηκαν.','Translation Memory cleared. %d cached block was removed.'=>'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.' . "\0" . 'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Η Lingua Forge είναι μια ολοκληρωμένη λύση SEO για πολλαπλές γλώσσες. Δεν απαιτείται επιπλέον πρόσθετο SEO.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Εάν έχετε εγκαταστήσει ένα γενικό πρόσθετο SEO, αυτό το πάνελ δείχνει πώς το LF προσαρμόζεται για να αποφύγει διπλή έξοδο. Ο στόχος είναι η αποφυγή συγκρούσεων — όχι η συνεργασία. Το LF παρέχει πάντα το πολύγλωσσο επίπεδο SEO (hreflang, og:locale, inLanguage schema) που απαιτεί γνώση της διαμόρφωσης δρομολόγησης γλώσσας του LF για σωστή παραγωγή.','Installed SEO plugins'=>'Εγκατεστημένα πρόσθετα SEO','Plugin'=>'Πρόσθετο','Status'=>'Κατάσταση','✓ Active'=>'✓ Ενεργό','— Not detected'=>'— Δεν ανιχνεύθηκε','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Δεν ανιχνεύθηκαν συγκρουόμενα πρόσθετα SEO. Η Lingua Forge χειρίζεται αυτόνομα όλη την έξοδο SEO.','What LF provides — and collision avoidance'=>'Τι παρέχει το LF — και αποφυγή συγκρούσεων','Feature'=>'Λειτουργία','LF provides'=>'Η LF παρέχει','When another SEO plugin is installed'=>'Όταν εγκαθίσταται άλλο SEO plugin','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Απενεργοποιημένο (με ρύθμιση)','✓ LF outputs — plugin hreflang suppressed'=>'✓ Εξόδοι LF — πρόσθετο hreflang κατασταλμένο','✓ LF outputs'=>'✓ Εξόδοι LF','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'Η LF παράγει ακριβείς hreflang για κάθε διαμορφωμένη γλώσσα, συμπεριλαμβανομένου του x-default. Τα γενικά πρόσθετα SEO δεν έχουν πρόσβαση στη διαμόρφωση δρομολόγησης LF και θα παρήγαγαν hreflang βάσει λανθασμένων υποθέσεων URL. Η LF καταστέλλει την έξοδό τους μέσω φίλτρου για να αποτρέψει συγκρούσεις.','Suppressed: %s.'=>'Κατασταλμένο: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Απενεργοποιημένο (ρύθμιση λειτουργίας)','→ Locale tags only — deferring base OG to plugin'=>'→ Μόνο ετικέτες τοπικής ρύθμισης — αναβάλλοντας το βασικό OG στο πρόσθετο','→ Locale tags only (manual setting)'=>'→ Μόνο ετικέτες τοπικής ρύθμισης (χειροκίνητη ρύθμιση)','✓ LF outputs full OG + Twitter Cards'=>'✓ Εξόδοι LF πλήρες OG + Twitter Cards','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'Το LF προσθέτει πάντα og:locale και og:locale:alternate — τα πολύγλωσσα σήματα που κανένα γενικό SEO plugin δεν μπορεί να παράγει σωστά. Για το βασικό σετ OG (og:title, og:description, og:image), το LF το παράγει όταν κανένα άλλο πρόσθετο δεν είναι παρόν. Όταν είναι εγκατεστημένο ένα SEO πρόσθετο, το LF παραλείπει το βασικό σετ για να αποφύγει διπλές ετικέτες — όχι επειδή το πρόσθετο είναι "καλύτερο", αλλά επειδή η διπλοτυπία δεν προσφέρει αξία.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Αναβλήθηκε σε plugin','✓ LF outputs Article / WebPage / WebSite'=>'✓ Εξόδοι LF Άρθρο / WebPage / Ιστότοπος','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'Η LF παράγει πολύγλωσσο JSON-LD με επισημάνσεις inLanguage συνδεδεμένες με τη διαμόρφωση δρομολόγησης γλώσσας. Όταν εγκαθίσταται ένα πρόσθετο SEO, η LF απενεργοποιεί εντελώς το δικό της σχήμα: τα διπλά γραφήματα JSON-LD παράγουν σφάλματα επικύρωσης και δεν υπάρχει καθαρός τρόπος να συμπληρώσετε ένα υπάρχον γράφημα.','XML Sitemap'=>'XML Sitemap','✓ Active at /lf-sitemap.xml'=>'✓ Ενεργό στο /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'Το LF δημιουργεί το δικό του sitemap με εναλλακτικά xhtml:link για όλες τις ομάδες μεταφράσεων. Όταν είναι εγκατεστημένο ένα SEO πρόσθετο, δημιουργεί ένα ξεχωριστό sitemap — και τα δύο συνυπάρχουν ανεξάρτητα. Υποβάλετε και τα δύο στη Google Search Console: το sitemap του SEO plugin για ανακάλυψη περιεχομένου, το sitemap του LF για σήματα σχέσεων γλώσσας.','Canonical tag'=>'Κανονική ετικέτα','✓ WP canonical replaced (self-referencing)'=>'✓ Αντικαταστάθηκε το κανονικό WP (αυτοαναφορικό)','WP core canonical active (hreflang disabled)'=>'Το πυρήνα του WordPress ενεργοποιεί το canonical (hreflang απενεργοποιημένο)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'Το LF αφαιρεί την κανονική ετικέτα του πυρήνα του WordPress και την αντικαθιστά με μια αυτοαναφορική κανονική που δείχνει στη σωστή URL με πρόθεμα γλώσσας. Όταν ενεργοποιείται ένα πρόσθετο SEO τρίτου μέρους (Yoast, Rank Math, AIOSEO, SEOPress), το LF αναβάλλει τη διαχείριση της κανονικής σε αυτό το πρόσθετο.','Legacy lf-social-share mu-plugin'=>'Παλιό μόνιμο πρόσθετο lf-social-share','The lf-social-share mu-plugin is active.'=>'Το πρόσθετο lf-social-share είναι ενεργό.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Τα ενσωματωμένα modules Κοινωνικής Κοινής Χρήσης και Open Graph της Lingua Forge καλύπτουν όλη τη λειτουργικότητα που παρέχει το mu-plugin, plus υποστήριξη πολύγλωσσου og:locale. Μπορείτε με ασφάλεια να απενεργοποιήσετε το mu-plugin.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Ετικέτες OG/Twitter Card: διαχειρίζεται από το module Open Graph της LF (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Κοινή χρήση μπλοκ κοινωνικών εικονιδίων: URLs: διαχειρίζεται από το ενσωματωμένο Κοινωνικό Μοιρασιά LF (SEO → Κοινωνική Μοιρασιά)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'ενέργειες copy/native/auto JS: διαχειρίζεται από το social-share.js του LF','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Ενώ είναι ενεργό, το πρόσθετο διαχειρίζεται το βασικό σετ OG και το LF εκπέμπει μόνο ετικέτες τοπικής γλώσσας (auto mode). Η αφαίρεσή του αλλάζει το LF σε πλήρη λειτουργία OG αυτόματα.','Debug Files'=>'Αρχεία αποσφαλμάτωσης','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Όταν ενεργοποιείται η καταγραφή αποσφαλμάτωσης (μέσω του διακόπτη παρακάτω ή ορίζοντας το LINGUAFORGE_AI_DEBUG στο wp-config.php), οι λειτουργίες μετάφρασης και μετάφρασης προτύπων FSE γράφουν τις ακατέργαστες προτροπές AI και τις απαντήσεις τους στον δίσκο για αποσφαλμάτωση. Χρησιμοποιήστε αυτήν την ενότητα για να παρακολουθείτε αυτήν την έξοδο και να την διαγράψετε μόλις έχετε ό,τι χρειάζεστε — τα αρχεία μπορούν να αυξηθούν γρήγορα σε μεγάλες σελίδες. Διαμορφώστε τον προορισμό καταλόγου μέσω του φίλτρου linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχείο αφαιρέθηκε.' . "\0" . 'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχεία αφαιρέθηκαν.','Debug logging enabled.'=>'Η καταγραφή αποσφαλμάτωσης ενεργοποιήθηκε.','Debug logging disabled.'=>'Η καταγραφή αποσφαλμάτωσης απενεργοποιήθηκε.','Debug logging'=>'Καταγραφή αποσφαλμάτωσης','Write AI prompts and responses to disk for troubleshooting'=>'Γράψτε προτροπές και απαντήσεις AI στον δίσκο για αποσφαλμάτωση','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΑΠΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Τα αρχεία καταλήγουν στον παρακάτω κατάλογο. Χρησιμοποιείται για διάγνωση θεμάτων μετάφρασης — απενεργοποιήστε μόλις έχετε ό,τι χρειάζεστε ώστε τα αρχεία να μην συσσωρεύονται. Μπορείτε επίσης να το επιβάλετε από το wp-config.php με `define( \'LINGUAFORGE_AI_DEBUG\', true );` που υπερισχύει αυτής της εναλλαγής.','Currently:'=>'Τρέχον: ','✓ Enabled'=>'✓ Ενεργό','✗ Disabled'=>'✗ Απενεργό','Directory'=>'Κατάλογος','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Φίλτρο με το linguaforge_debug_dir για ανακατεύθυνση της εξόδου αποσφαλμάτωσης σε μη δημόσιο προορισμό.','Files'=>'Αρχεία','.txt file(s) in the directory'=>'.txt αρχεία στον κατάλογο','Save Debug Setting'=>'Αποθήκευση ρύθμισης αποσφαλμάτωσης','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Διαγραφή όλων των αρχείων .txt στον κατάλογο αποσφαλμάτωσης; Ο ίδιος ο κατάλογος θα παραμείνει ώστε οι μελλοντικές εγγραφές αποσφαλμάτωσης να καταλήγουν καθαρές.','Clear Debug Files'=>'Διαγραφή αρχείων αποσφαλμάτωσης','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Η Lingua Forge παράγει ετικέτες <link rel="alternate" hreflang> για κάθε διαμορφωμένη γλώσσα σε κάθε σελίδα, συμπεριλαμβανομένου του x-default που δείχνει στη γλώσσα πηγής. Αυτό είναι το κύριο σήμα πολ multilingual SEO για την Google και άλλες μηχανές αναζήτησης — δεν απαιτείται πρόσθετο plugin SEO.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Όταν είναι ενεργά, τα SEO plugins όπως Yoast SEO, Rank Math, All in One SEO ή SEOPress, το Lingua Forge καταστέλλει αυτόματα την έξοδο hreflang τους μέσω φίλτρου. Τα γενικά SEO plugins παράγουν hreflang βάσει δομής URL με μία γλώσσα και δεν μπορούν να λάβουν υπόψη τη διαμόρφωση πολυγλωσσικής δρομολόγησης σας. Η έξοδος του LF είναι πάντα σωστή.','Hreflang settings saved.'=>'Οι ρυθμίσεις hreflang αποθηκεύτηκαν.','Hreflang output'=>'Έξοδος hreflang','Output hreflang tags in wp_head'=>'Εξαγωγή ετικετών hreflang στο wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Απενεργοποίηση μόνο για ιστότοπους χωρίς κεφαλίδα ή πλήρως προσαρμοσμένες υλοποιήσεις hreflang. Όταν απενεργοποιείται, το LF δεν αφαιρεί πλέον το canonical tag του πυρήνα WordPress και δεν καταστέλλει πλέον την έξοδο hreflang του SEO plugin.','Current status'=>'Τρέχουσα κατάσταση','✓ Hreflang active'=>'✓ Ενεργό Hreflang','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'Το LF εξάγει ετικέτες hreflang και αντικαθιστά το κανονικό WordPress core με ένα αυτοαναφορικό κανονικό για κάθε έκδοση γλώσσας.','LF is suppressing hreflang output from: %s'=>'Το LF καταστέλλει την έξοδο hreflang από: %s','Save Hreflang Settings'=>'Αποθήκευση ρυθμίσεων Hreflang','Language Overrides'=>'Παρακάμψεις Γλώσσας','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Ανεβάστε συμπιεσμένα αρχεία .mo για να παρακάμψετε τις συμβολοσειρές πρόσθετου τρίτου μέρους για συγκεκριμένες τοπικές ρυθμίσεις — για παράδειγμα, μια προσαρμοσμένη μετάφραση VikBooking που χρησιμοποιεί "διαμέρισμα" αντί για "δωμάτιο". Τα αρχεία πρέπει να ακολουθούν τη συμβατική ονοματοδοσία του WordPress: {textdomain}-{locale}.mo (π.χ. vikbooking-ca.mo). Αποθηκεύονται στον φάκελο ανεβάσματος και επιβιώνουν από ενημερώσεις πρόσθετων.','Override file uploaded successfully.'=>'Το αρχείο παρακάμψεων ανέβηκε με επιτυχία.','Override file deleted.'=>'Το αρχείο παρακάμψεων διαγράφηκε.','No file was selected.'=>'Δεν επιλέχθηκε αρχείο.','Only .mo files are accepted.'=>'Επιτρέπονται μόνο αρχεία .mo.','The upload failed — please try again.'=>'Η μεταφόρτωση απέτυχε — παρακαλώ δοκιμάστε ξανά.','Could not save the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αποθήκευση του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Invalid filename.'=>'Μη έγκυρο όνομα αρχείου.','Security check failed — file path is not permitted.'=>'Απέτυχε ο έλεγχος ασφαλείας — η διαδρομή αρχείου δεν επιτρέπεται.','An unknown error occurred.'=>'Παρουσιάστηκε άγνωστο σφάλμα.','Text domain / locale'=>'Τομέας / τοπική ρύθμιση','Size'=>'Μέγεθος','Delete all files for this override (both .mo and .po)?'=>'Διαγράψτε όλα τα αρχεία αυτής της παρακάμψεως (τόσο .mo όσο και .po);','Delete'=>'Διαγραφή','No override files uploaded yet.'=>'Δεν έχουν ανέβει ακόμη αρχεία παρακάμψεων.','Upload .mo file'=>'Ανέβασμα αρχείου .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Δέχεται μόνο συμπιεσμένα αρχεία .mo. Το όνομα αρχείου πρέπει να ακολουθεί το μοτίβο {textdomain}-{locale}.mo. Η μεταφόρτωση αρχείου με το ίδιο όνομα με υπάρχον θα το αντικαταστήσει.','Upload Override'=>'Ανέβασμα Παρακάμψεων','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Αντιγραφή σε Ασφαλή Αποθήκευση','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Το Loco Translate αποθηκεύει τις προσαρμοσμένες μεταφράσεις του στον φάκελο wp-content/languages/loco/ — μια τοποθεσία που μπορεί να διαγραφεί σιωπηλά με ενημέρωση πυρήνα WP, επανεγκατάσταση πρόσθετου ή αν το Loco Translate αφαιρεθεί. Η αντιγραφή αρχείων εδώ τα μεταφέρει στον κατάλογο Lingua Forge i18n-overrides, ο οποίος διατηρείται μέσω όλων αυτών των γεγονότων και φορτώνεται αυτόματα σε κάθε αίτημα.','File copied to safe storage successfully.'=>'Το αρχείο αντιγράφηκε με επιτυχία σε ασφαλή αποθήκευση.','Source file not found.'=>'Το αρχείο πηγής δεν βρέθηκε.','Could not copy the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αντιγραφή του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Invalid file reference.'=>'Μη έγκυρη αναφορά αρχείου.','Type'=>'Τύπος','✓ In safe storage'=>'✓ Σε ασφαλή αποθήκευση','Copy to safe storage'=>'Αντιγραφή σε ασφαλή αποθήκευση','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Δεν έχουν βρεθεί ακόμη προσαρμοσμένα αρχεία Loco Translate. Εμφανίζονται εδώ μόλις αποθηκεύσετε μια μετάφραση στο Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Η Lingua Forge παράγει μετα-ετικέτες Open Graph και Twitter Card ώστε οι κοινόχρηστοι URLs να εμφανίζουν τη σωστή γλώσσα, τίτλο, περιγραφή και εικόνα σε κοινωνικές πλατφόρμες.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Σε αντίθεση με το hreflang — όπου το LF πάντα υπερισχύει άλλων πρόσθετων επειδή δεν μπορούν να γνωρίζουν τη πολυγλωσσική διαμόρφωσή σας — το Open Graph διαφέρει: τα πρόσθετα Yoast, Rank Math και παρόμοια ήδη παράγουν σωστά tags OG για το περιεχόμενό σας. Η διπλοεγγραφή τους δεν προσθέτει αξία. Σε αυτόματο mode, το LF ανιχνεύει ενεργά SEO plugins και προσθέτει μόνο ό,τι δεν μπορούν να παρέχουν: og:locale (τρέχουσα γλώσσα) και og:locale:alternate (όλες οι άλλες διαμορφωμένες γλώσσες).','Open Graph settings saved.'=>'Οι ρυθμίσεις Open Graph αποθηκεύτηκαν.','Open Graph output'=>'Έξοδος Open Graph','Output Open Graph tags in wp_head'=>'Εξαγωγή ετικετών Open Graph στο wp_head','Output mode'=>'Λειτουργία εξαγωγής','Auto (recommended)'=>'Αυτόματο (συνιστάται)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Ανίχνευση ενεργών πρόσθετων SEO (Yoast, Rank Math, κ.λπ.) κατά την εκτέλεση. Εκπέμπει μόνο og:locale + og:locale:alternate όταν ένα άλλο πρόσθετο ήδη παράγει το πλήρες σετ OG. Εκπέμπει το πλήρες σετ όταν κανένα δεν ανιχνεύεται.','Locale only'=>'Μόνο τοπική ρύθμιση','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Πάντα εκπέμπετε μόνο og:locale και og:locale:alternate. Χρησιμοποιήστε όταν ένα άλλο πρόσθετο ή θέμα διαχειρίζεται το πλήρες σύνολο OG.','Full'=>'Πλήρες','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Πάντα εκπέμπετε το πλήρες σύνολο OG + Twitter Card ανεξάρτητα από άλλα πρόσθετα. Χρησιμοποιήστε μόνο αν κανένα άλλο πρόσθετο δεν παράγει ετικέτες OG.','Disabled'=>'Απενεργοποιημένο','Do not output any OG tags.'=>'Μην παράγετε κανένα OG tag.','Default OG image'=>'Προεπιλεγμένη εικόνα OG','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL εφεδρικής εικόνας που χρησιμοποιείται όταν μια σελίδα δεν έχει επιλεγμένη εικόνα, λογότυπο ιστότοπου ή εικονίδιο ιστότοπου. Εμφανίζεται σε κοινωνικές προεπισκοπήσεις για αρχεία, τον δείκτη ιστολογίου και οποιαδήποτε μοναδική σελίδα χωρίς μικρογραφία.','— Disabled'=>'— Απενεργοποιήθηκε','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Ενεργό — ετικέτες τοπικής ρύθμισης (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Ενεργό — πλήρες OG + Twitter Cards','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Εντοπίστηκε παλιό μόνιμο πρόσθετο lf-social-share. Το LF αναβάλλει το βασικό σετ OG στο μόνιμο πρόσθετο και παράγει μόνο og:locale + og:locale:alternate. Μπορείτε να απενεργοποιήσετε το μόνιμο πρόσθετο — το ενσωματωμένο Κοινωνικό Μοιρασμό του LF (Επισκόπηση SEO → Κοινωνικός Μοιρασμός) και το Open Graph καλύπτουν την ίδια λειτουργικότητα.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Εντοπίστηκαν plugin(τα) SEO: %s. Το LF εμφανίζει μόνο og:locale και og:locale:alternate; το ανιχνευμένο plugin χειρίζεται ολόκληρο το σετ OG.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Δεν ανιχνεύθηκε εξωτερικό πρόσθετο OG. Η LF παράγει ολόκληρο το σετ OG + Twitter Card.','Save Open Graph Settings'=>'Αποθήκευση ρυθμίσεων Open Graph','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Η Lingua Forge παράγει δομημένα δεδομένα Schema.org JSON-LD ώστε οι μηχανές αναζήτησης να κατανοούν τον τύπο περιεχομένου, τη γλώσσα και τα μεταδεδομένα σας. Αυτός είναι ο κύριος τρόπος επικοινωνίας των annotations inLanguage για πολύγλωσσο περιεχόμενο προς την Google και άλλους crawlers.','Schema output deferred.'=>'Η έξοδος Schema αναβλήθηκε.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'Το %s είναι ενεργό και ήδη παράγει JSON-LD Schema.org. Το Lingua Forge έχει απενεργοποιήσει την δική του έξοδο schema για να αποτρέψει συγκρουόμενα γραφήματα. Σε αντίθεση με το Open Graph — όπου το LF προσθέτει og:locale πάνω από την έξοδο ενός άλλου πρόσθετου — το schema δεν μπορεί να συμπληρωθεί καθαρά: διπλά ή επικαλυπτόμενα JSON-LD γραφήματα προκαλούν σφάλματα επικύρωσης. Απενεργοποιήστε την έξοδο schema στο ανιχνευμένο πρόσθετο αν θέλετε το LF να διαχειρίζεται τα δομημένα δεδομένα.','Schema.org settings saved.'=>'Οι ρυθμίσεις Schema.org αποθηκεύτηκαν.','Schema.org output'=>'Έξοδος Schema.org','Output Schema.org JSON-LD in wp_head'=>'Έξοδος Schema.org JSON-LD στο wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Κλειδωμένο — ενεργό ένα συγκρουόμενο πρόσθετο SEO. Δείτε την ειδοποίηση παραπάνω.','Article / WebPage'=>'Άρθρο / Ιστοσελίδα','Output Article or WebPage schema on singular posts and pages'=>'Εξαγωγή σχήματος Article ή WebPage σε μεμονωμένες αναρτήσεις και σελίδες','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Τα άρθρα ιστολογίου χρησιμοποιούν το Article· όλοι οι άλλοι τύποι δημοσιεύσεων και σελίδες χρησιμοποιούν WebPage. Περιλαμβάνει τίτλο, περιγραφή, inLanguage, url, datePublished, dateModified, εικόνα και εκδότη.','WebSite'=>'Ιστότοπος','Output WebSite schema on the front page and blog index'=>'Έξοδος schema Ιστότοπου στη αρχική σελίδα και στον κατάλογο ιστολογίου','Includes site name, url, and inLanguage.'=>'Περιλαμβάνει όνομα ιστότοπου, url και inLanguage.','Product'=>'Προϊόν','Output Product schema on WooCommerce product pages'=>'Εξαγωγή σχήματος Προϊόντος σε σελίδες προϊόντων WooCommerce','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Περιλαμβάνει όνομα, περιγραφή, inLanguage, url, εικόνα και μια Προσφορά με τιμή, νόμισμα τιμής και διαθεσιμότητα. Η τιμή και η διαθεσιμότητα προέρχονται από το προϊόν της πηγής (μοντέλο κοινόχρηστου αποθέματος).','Currently emitting'=>'Αυτή τη στιγμή εκπέμπεται','Article / WebPage — all singular posts and pages'=>'Άρθρο / Ιστοσελίδα — όλα τα μεμονωμένα άρθρα και σελίδες','WebSite — front page / blog index'=>'Ιστότοπος — αρχική σελίδα / ευρετήριο ιστολογίου','Product — WooCommerce product pages'=>'Προϊόν — σελίδες προϊόντων WooCommerce','Nothing — all types disabled'=>'Τίποτα — όλοι οι τύποι απενεργοποιημένοι','Save Schema.org Settings'=>'Αποθήκευση ρυθμίσεων Schema.org','Blog / Editorial'=>'Ιστολόγιο / Συντακτική','Product / eCommerce'=>'Προϊόν / Ηλεκτρονικό εμπόριο','Landing / Short-form'=>'Προσγείωση / Μικρής μορφής','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Φιλτράρισμα κατά γλώσσα και τύπο ανάρτησης, περιήγηση στο περιεχόμενό σας και κλικ στην Ανάλυση σε οποιοδήποτε στοιχείο για εκτέλεση ελέγχου SEO βάσει κανόνων — μήκος τίτλου, μετα-περιγραφή, αριθμός λέξεων, δομή επικεφαλίδων, κάλυψη εναλλακτικών εικόνων, και εσωτερικοί σύνδεσμοι.','Treat H2 as H1 equivalent'=>'Αντιμετώπιση H2 ως H1 ισοδύναμο','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Ενεργοποιήστε όταν το θέμα σας εμφανίζει τον τίτλο ως H2 αντί για H1 (συνήθως σε ορισμένα μπλοκ θέματα). Ο αναλυτής λαμβάνει τη σελίδα που εμφανίζεται και, αν δεν βρει H1 αλλά βρει H2, προωθεί το πρώτο H2 σε H1 για σκοπούς βαθμολόγησης.','Save analysis settings'=>'Αποθήκευση ρυθμίσεων ανάλυσης','Per-Post Analysis'=>'Ανάλυση ανά ανάρτηση','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Επιλέξτε μια ανάρτηση και εκτελέστε λεπτομερή έλεγχο SEO για να δείτε αποτελέσματα ανά μετρική και μια βαθμολογία για αυτό το συγκεκριμένο στοιχείο.','Language'=>'Γλώσσα','source'=>'πηγή','All types'=>'Όλοι οι τύποι','Load content'=>'Φόρτωση περιεχομένου','Batch Analysis'=>'Μαζική ανάλυση','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Εκτελέστε πλήρη έλεγχο SEO σε όλες τις δημοσιευμένες αναρτήσεις για μία ή όλες τις ενεργές γλώσσες. Οι βαθμολογίες αποθηκεύονται ανά ανάρτηση και αντικατοπτρίζονται στα εμβλήματα στη στήλη Γλώσσα στη λίστα αναρτήσεων.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Οι σελίδες συστήματος WooCommerce (Κατάστημα, Καλάθι, Ολοκλήρωση αγοράς, Ο λογαριασμός μου) εξαιρούνται — το περιεχόμενό τους διαχειρίζεται το WooCommerce και δεν μπορεί να βελτιωθεί μέσω επεξεργασίας SEO.','Post type'=>'Τύπος ανάρτησης','Default profile'=>'Προεπιλεγμένο προφίλ','— Auto-detect —'=>'— Αυτόματη ανίχνευση —','Analyse all languages'=>'Ανάλυση όλων των γλωσσών','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Αυτόματη ανίχνευση αναθέσεων: προϊόντα WooCommerce → προφίλ προϊόντος; η στατική αρχική σελίδα → προφίλ προορισμού; όλα τα άλλα → προφίλ ιστολογίου. Επιλέξτε ένα συγκεκριμένο προφίλ για να το αντικαταστήσετε σε όλα τα posts.','%d post'=>'%d ανάρτηση' . "\0" . '%d αναρτήσεις','Last run: %s ago'=>'Τελευταία εκτέλεση: %s πριν','Never run'=>'Ποτέ μην τρέχετε','avg'=>'μέσος όρος','(partial)'=>'(μερικό)','Analyse'=>'Ανάλυση','(no title) #%d'=>'(χωρίς τίτλο) #%d','Invalid post ID.'=>'Μη έγκυρο ID ανάρτησης.','Post not found or not published.'=>'Δεν βρέθηκε ή δεν δημοσιεύτηκε η ανάρτηση.','~%d min read'=>'~%d λεπτά ανάγνωση' . "\0" . '~%d λεπτά ανάγνωση','No title set.'=>'Δεν έχει οριστεί τίτλος.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Ο τίτλος είναι %1$d χαρακτήρες — ενδέχεται να περικοπεί στα SERPs (στοχεύστε κάτω από %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Ο τίτλος είναι μόνο %d χαρακτήρες — στοχεύστε για τουλάχιστον 10 χαρακτήρες.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Τίτλος με μία λέξη (%d χαρακτήρες) — η προσθήκη δεύτερης λέξης βελτιώνει την σαφήνεια και την κάλυψη λέξεων-κλειδιών.','%1$d chars, %2$d words — good title.'=>'%1$d χαρακτήρες, %2$d λέξεις — καλός τίτλος.','Using LF AI meta description.'=>'Χρησιμοποιώντας μετα-περιγραφή AI του LF.','No LF meta description set — using excerpt/content.'=>'Δεν έχει οριστεί μετα-περιγραφή LF — χρησιμοποιώντας απόσπασμα/περιεχόμενο.','No meta description found. Generate one via the AI meta description feature.'=>'Δεν βρέθηκε μετα-περιγραφή. Δημιουργήστε μία μέσω της λειτουργίας μετα-περιγραφής AI.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d χαρακτήρες — πολύ σύντομο (στοχεύστε για %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d χαρακτήρες — πιθανώς περικομμένοι στα αποτελέσματα SERP (κρατήστε κάτω από %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d χαρακτήρες — καλό, ελαφρώς πάνω από το ιδανικό %2$d αλλά εντός του αποδεκτού εύρους των %3$d χαρακτήρων. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d χαρακτήρες — ιδανικό μήκος. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d λέξεις — πολύ λεπτό περιεχόμενο. Σκεφτείτε να επεκτείνετε σε τουλάχιστον %2$d λέξεις.','%1$d words — below recommended minimum of %2$d.'=>'%1$d λέξεις — κάτω από το συνιστώμενο ελάχιστο των %2$d.','%d words.'=>'%d λέξεις.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Ενεργοποιήθηκε η λειτουργία H2 ως H1 — ο τίτλος μετράει ως ισοδύναμο H1. (Οι επικεφαλίδες ενδέχεται να μην ανιχνεύονται από τη σελίδα που εμφανίζεται. Επιβεβαιώστε ότι το θέμα σας εμφανίζει σωστά τον τίτλο.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Δεν βρέθηκε H1. Συνήθως ο τίτλος της ανάρτησης είναι το H1 — επαληθεύστε ότι το θέμα σας το παράγει.','%d H1 tags found — a page should have exactly one H1.'=>'Βρέθηκαν %d ετικέτες H1 — μια σελίδα πρέπει να έχει ακριβώς μία H1.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — χωρίς H2, αλλά βρέθηκαν %d υποτίτλοι H3 (π.χ. επικεφαλίδες accordion/λεπτομέρειες). Η δομή είναι αποδεκτή.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — σύντομο περιεχόμενο (%d παράγραφοι), οι υποτίτλοι δεν είναι απαραίτητοι.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — χωρίς υπο-επικεφαλίδες H2 (αποδεκτό για αυτόν τον τύπο περιεχομένου).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — δεν βρέθηκαν H2 ή H3 υποκεφάλαια. Η προσθήκη H2 βελτιώνει τη δομή.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Δεν βρέθηκαν εικόνες στο περιεχόμενο.','%1$d of %2$d image(s) missing alt text.'=>'%1$d από %2$d εικόνες λείπει το εναλλακτικό κείμενο.','%d image(s), all have alt text.'=>'%d εικόνες, όλες έχουν εναλλακτικό κείμενο.','No links found. Internal links improve crawlability and user navigation.'=>'Δεν βρέθηκαν σύνδεσμοι. Οι εσωτερικοί σύνδεσμοι βελτιώνουν την ανίχνευση και την πλοήγηση των χρηστών.','No links found.'=>'Δεν βρέθηκαν σύνδεσμοι.','%d external link(s), no internal links. Add internal links to related content.'=>'%d εξωτερικοί σύνδεσμοι, κανένας εσωτερικός. Προσθέστε εσωτερικούς συνδέσμους σε σχετικό περιεχόμενο.','%d external link(s), no internal links.'=>'%d εξωτερικοί σύνδεσμοι, χωρίς εσωτερικούς συνδέσμους.','%1$d internal, %2$d external.'=>'%1$d εσωτερικοί, %2$d εξωτερικοί.','Post not found.'=>'Η ανάρτηση δεν βρέθηκε.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Δεν έχει διαμορφωθεί πάροχος AI. Προσθέστε ένα κλειδί API στις Ρυθμίσεις → Κλειδιά API.','No response from AI provider. Check your API key and try again.'=>'Δεν λαμβάνεται απάντηση από τον πάροχο AI. Ελέγξτε το κλειδί API και δοκιμάστε ξανά.','AI returned an unexpected response format. Please try again.'=>'Η AI επέστρεψε μια απροσδόκητη μορφή απάντησης. Παρακαλώ δοκιμάστε ξανά.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Η Lingua Forge δημιουργεί ένα αποκλειστικό XML sitemap στη διεύθυνση /lf-sitemap.xml που προσθέτει εναλλακτικούς συνδέσμους γλώσσας για όλο το μεταφρασμένο περιεχόμενό σας. Αυτό το sitemap συμπληρώνει το sitemap του πυρήνα WordPress και οποιοδήποτε sitemap πρόσθετου SEO — δεν το αντικαθιστά.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Το sitemap του WordPress περιλαμβάνει όλους τους URL περιεχομένου σας. Το sitemap LF δείχνει στις μηχανές αναζήτησης πώς οι εκδόσεις γλώσσας σχετίζονται μεταξύ τους μέσω εναλλακτικών xhtml:link hreflang. Υποβάλετε και τα δύο στο Google Search Console για πλήρη κάλυψη.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'Το %s είναι ενεργό και δημιουργεί το δικό του χάρτη ιστοτόπου. Αυτός ο χάρτης είναι ξεχωριστός από τον χάρτη του LF. Και οι δύο πρέπει να υποβληθούν στη Google Search Console: ο χάρτης ιστοτόπου του SEO plugin καταγράφει το περιεχόμενό σας· ο χάρτης του LF προσθέτει τις πολυγλωσσικές εναλλακτικές συνδέσεις. Ο χάρτης του LF ανακοινώνεται αυτόματα στο robots.txt.','Sitemap settings saved.'=>'Οι ρυθμίσεις Sitemap αποθηκεύτηκαν.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Ο προσωρινός αποθηκευτικός χώρος του Sitemap καθαρίστηκε. Θα αναδημιουργηθεί στην επόμενη επίσκεψη στη διεύθυνση URL του sitemap.','Sitemap output'=>'Έξοδος Sitemap','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Δημιουργία πολύγλωσσου sitemap στο /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Όταν ενεργοποιείται, το URL του sitemap ανακοινώνεται αυτόματα στο robots.txt και η προσωρινή μνήμη ανανεώνεται όταν αποθηκεύεται το μεταφρασμένο περιεχόμενο.','Sitemap URL'=>'Διεύθυνση URL Sitemap','Submit this URL to Google Search Console alongside your main sitemap.'=>'Υποβάλετε αυτό το URL στη Google Search Console μαζί με το κύριο sitemap σας.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Δεν έχει ακόμη δημιουργηθεί. Το sitemap δημιουργείται κατά την πρώτη επίσκεψη στη διεύθυνση sitemap και αποθηκεύεται στην cache για 24 ώρες.','✓ Active — %d URL entry with language alternates'=>'✓ Ενεργό — %d καταχώριση URL με εναλλακτικές γλώσσες' . "\0" . '✓ Ενεργό — %d καταχωρίσεις URL με εναλλακτικές γλώσσες','No translated content found. The sitemap will populate once posts have been translated.'=>'Δεν βρέθηκε μεταφρασμένο περιεχόμενο. Το sitemap θα γεμίσει μόλις μεταφραστούν οι αναρτήσεις.','Last generated: %s'=>'Τελευταία γεννήθηκε: %s','Save Sitemap Settings'=>'Αποθήκευση ρυθμίσεων Sitemap','Flush Sitemap Cache'=>'Εκκαθάριση cache sitemap','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Επιβάλλει την ανανέωση του sitemap στην επόμενη αίτηση. Χρησιμοποιήστε μετά την μαζική εισαγωγή ή χειροκίνητη επεξεργασία των σχέσεων μετάφρασης.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'Το IndexNow είναι ένα ανοιχτό πρωτόκολλο που υποστηρίζεται από το Bing, Yandex και άλλες μηχανές αναζήτησης. Όταν δημοσιεύεται ή ενημερώνεται μια μεταφρασμένη ανάρτηση, το Lingua Forge ειδοποιεί αυτόματα όλες τις συμμετέχουσες μηχανές σε μια ενιαία αποστολή — χωρίς ερωτήματα, χωρίς αναμονή για το επόμενο crawl robots.txt.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'Το IndexNow αντικαθιστά τα αποσυρμένα endpoints Bing και Yandex sitemap-ping. Η Google ανακαλύπτει τα sitemap μέσω της οδηγίας Sitemap: στο robots.txt όπως και πριν.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Όλες οι URL που υποβλήθηκαν στο IndexNow είναι επιτυχείς.','No translated URLs found to submit. Publish some translated posts first.'=>'Δεν βρέθηκαν μεταφρασμένες διευθύνσεις URL για υποβολή. Δημοσιεύστε πρώτα μερικές μεταφρασμένες αναρτήσεις.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ Η υποβολή IndexNow απέτυχε. Ελέγξτε αν το αρχείο κλειδιού είναι προσβάσιμο δημόσια (δείτε παρακάτω) και δοκιμάστε ξανά.','Verification key'=>'Κλειδί επαλήθευσης','Key file served automatically at: %s'=>'Το αρχείο κλειδιού σερβίρεται αυτόματα στη διεύθυνση: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Το κλειδί δεν μπόρεσε να δημιουργηθεί. Ελέγξτε αν ο ιστότοπος έχει δικαίωμα εγγραφής στις επιλογές του WordPress.','Key file status'=>'Κατάσταση αρχείου κλειδιού','✓ Key file is publicly reachable.'=>'✓ Το αρχείο κλειδιού είναι προσβάσιμο δημόσια.','✗ Key file is not reachable.'=>'✗ Το αρχείο κλειδιού δεν είναι προσβάσιμο.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'Οι μηχανές IndexNow επαληθεύουν το αρχείο κλειδιού πριν δεχθούν υποβολές. Αν το αρχείο δεν είναι προσβάσιμο, οι υποβολές θα απορριφθούν με σφάλμα 403.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Κοινές αιτίες: caching ολόκληρης σελίδας (αποκτήστε το), ένα πρόσθετο ασφαλείας που μπλοκάρει αρχεία .txt, ή ένας προσαρμοσμένος κανόνας Nginx/Apache. Το αρχείο σερβίρεται από το LF σε κάθε αίτημα — κανένα φυσικό αρχείο δεν γράφεται στον δίσκο.','Submit all URLs'=>'Υποβάλετε όλες τις διευθύνσεις URL','Submit all URLs via IndexNow'=>'Υποβολή όλων των URL μέσω IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Αποστέλλει κάθε δημοσιευμένο URL που διαχειρίζεται το LF στο IndexNow σε μια παρτίδα. Η αυτόματη υποβολή τρέχει ήδη σε κάθε δημοσίευση/ενημέρωση — χρησιμοποιήστε το μόνο μετά από μαζική εισαγωγή ή όταν ρυθμίζετε το IndexNow για πρώτη φορά.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Η Google δεν συμμετέχει στο IndexNow. Ανακαλύπτει χάρτες ιστότοπου μέσω της οδηγίας Sitemap: του αρχείου robots.txt — την οποία το LF έχει ήδη διαμορφώσει. Χρησιμοποιήστε τη Google Search Console για παρακολούθηση της κάλυψης ευρετηρίασης.','Open Search Console →'=>'Άνοιγμα Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'Το robots.txt ενημερώθηκε με οδηγία Sitemap.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Βρίσκεται φυσικό αρχείο robots.txt. Η οδηγία Sitemap του LF είναι παρούσα.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Υπάρχει ένα φυσικό αρχείο robots.txt στη ρίζα του ιστότοπου. Το εικονικό robots.txt του WordPress — και το Sitemap: φίλτρο του LF — παρακάμπτονται. Ο χάρτης ιστοτόπου του LF δεν ανακοινώνεται στις μηχανές αναζήτησης.','Add Sitemap directive to robots.txt'=>'Προσθέστε την οδηγία Sitemap στο robots.txt','Appends the following line to your existing robots.txt: %s'=>'Προσθέτει την παρακάτω γραμμή στο υπάρχον robots.txt σας: %s','DISALLOW_FILE_MODS is set.'=>'Το DISALLOW_FILE_MODS έχει οριστεί.','Add the following line to your robots.txt manually:'=>'Προσθέστε χειροκίνητα την παρακάτω γραμμή στο robots.txt σας:','View current robots.txt'=>'Προβολή τρέχοντος robots.txt','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Δεν βρέθηκε φυσικό αρχείο robots.txt. Το WordPress το δημιουργεί εικονικά και η οδηγία Sitemap της LF περιλαμβάνεται αυτόματα.','The following directive is active in your virtual robots.txt:'=>'Η ακόλουθη οδηγία είναι ενεργή στο εικονικό αρχείο robots.txt σας:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Οι τροποποιήσεις αρχείων είναι απενεργοποιημένες (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Δεν ήταν δυνατή η εγγραφή στο robots.txt. Ελέγξτε τα δικαιώματα αρχείων.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Η Lingua Forge επεκτείνει το μπλοκ Κοινωνικών Εικονιδίων του WordPress Core με δυναμικούς URLs κοινής χρήσης. Ορίστε οποιονδήποτε σύνδεσμο εικονιδίου σε τιμή "share:" και η LF το ξαναγράφει στον σωστό σύνδεσμο κοινής χρήσης ή ενέργεια JavaScript κατά την απόδοση — χωρίς ανάγκη για προσαρμοσμένο κώδικα ή πρόσθετο τρίτου μέρους.','Social Share settings saved.'=>'Οι ρυθμίσεις Κοινωνικής Κοινοποίησης αποθηκεύτηκαν.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Το ενσωματωμένο Κοινωνικό Μοιρασιά της Lingua Forge είναι ανενεργό — το πρόσθετο διαχειρίζεται την ανακατεύθυνση URL κοινής χρήσης και τις ενέργειες JS.','Social Share'=>'Κοινωνική Μοιρασιά','Enable Social Share URL rewriting for Social Icons blocks'=>'Ενεργοποίηση ανακατεύθυνσης URL κοινωνικής κοινής χρήσης για μπλοκ εικονιδίων κοινωνικής δικτύωσης','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Απενεργοποιημένο επειδή το μόνιμο πρόσθετο lf-social-share ήδη παρέχει αυτή τη λειτουργία.','Save Social Share Settings'=>'Αποθήκευση ρυθμίσεων Κοινωνικής Μοιρασιάς','How to use'=>'Πώς να χρησιμοποιήσετε','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Στον επεξεργαστή μπλοκ, προσθέστε ένα μπλοκ Εικονιδίων Κοινωνικής Δικτύωσης. Για κάθε εικονίδιο, ανοίξτε τις ρυθμίσεις συνδέσμου και εισάγετε μία από τις τιμές "share:" παρακάτω ως το URL. Στην εμπρόσθια όψη, το LF το αντικαθιστά με το σωστό URL κοινής χρήσης για την τρέχουσα σελίδα.','External share services'=>'Εξωτερικές υπηρεσίες κοινής χρήσης','URL to enter'=>'URL προς εισαγωγή','Action'=>'Ενέργεια','Share on Facebook'=>'Μοιραστείτε στο Facebook','Post on X / Twitter'=>'Ανάρτηση στο X / Twitter','Share on LinkedIn'=>'Μοιραστείτε στο LinkedIn','Send via WhatsApp'=>'Αποστολή μέσω WhatsApp','Send via Telegram'=>'Αποστολή μέσω Telegram','Submit to Reddit'=>'Υποβολή στο Reddit','Pin on Pinterest'=>'Καρφιτσώστε στο Pinterest','Share on Mastodon'=>'Μοιραστείτε στο Mastodon','Share via email (mailto:)'=>'Μοιραστείτε μέσω email (mailto:)','JavaScript-powered actions'=>'Ενέργειες με JavaScript','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Αντιγράψτε την τρέχουσα διεύθυνση URL στο πρόχειρο. Εμφανίζει μήνυμα "Ο σύνδεσμος αντιγράφηκε" με επιτυχία.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Ανοίξτε το εγγενές φύλλο κοινής χρήσης ιστού του περιηγητή (iOS, Android, μερικοί επιτραπέζιοι υπολογιστές). Επιστρέφει στην αντιγραφή στο clipboard αν δεν υποστηρίζεται.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Χρησιμοποιήστε εγγενή κοινή χρήση όταν είναι διαθέσιμη; αλλιώς αντιγράψτε στο clipboard. Συνιστώμενο προεπιλεγμένο για κουμπιά "Κοινή χρήση".','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Το URL κοινής χρήσης πάντα αντικατοπτρίζει την τρέχουσα σελίδα — δεν χρειάζεται χειροκίνητη εισαγωγή URL. Το φίλτρο linguaforge_social_share_url σας επιτρέπει να παρακάμψετε το επιλυμένο URL για οποιαδήποτε υπηρεσία.','Configuration issue: WP site language has no content on this site'=>'Πρόβλημα διαμόρφωσης: Η γλώσσα του ιστότοπου WP δεν έχει περιεχόμενο σε αυτόν τον ιστότοπο','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'Η γλώσσα του ιστότοπου WordPress (%1$s) αντιστοιχεί στον κωδικό γλώσσας "%2$s", αλλά κανένα άρθρο σε αυτόν τον ιστότοπο δεν έχει ετικέτα _lf_lang=%2$s. Αυτό προκαλεί ερωτήματα προϊόντων WooCommerce να επιστρέφουν μηδενικά αποτελέσματα, εικόνες προϊόντων να αποτυγχάνουν και όλα τα ερωτήματα περιεχομένου που φιλτράρονται κατά γλώσσα να σπάνε.','Fix: go to'=>'Επιδιόρθωση: μεταβείτε στο','Settings → General → Site Language'=>'Ρυθμίσεις → Γενικά → Γλώσσα ιστότοπου','and set it to one of your actual content languages (e.g. %s).'=>'και ορίστε το σε μία από τις πραγματικές σας γλώσσες περιεχομένου (π.χ. %s).','Environment'=>'Περιβάλλον','Lingua Forge version'=>'Έκδοση Lingua Forge','WordPress version'=>'Έκδοση WordPress','PHP version'=>'Έκδοση PHP','Active theme'=>'Ενεργό θέμα','(FSE / block theme)'=>'(FSE / θέμα μπλοκ)','(classic theme)'=>'(κλασικό θέμα)','URL structure'=>'Δομή URL','Subdomain (de.example.com)'=>'Υποτομέας (de.example.com)','Path prefix (/de/)'=>'Πρόθεμα διαδρομής (/de/)','WP instance language'=>'Γλώσσα εγκατάστασης WP','not a content language — see notice above'=>'όχι γλώσσα περιεχομένου — δείτε την ειδοποίηση παραπάνω','Primary content language'=>'Γλώσσα κύριου περιεχομένου','Active languages'=>'Ενεργές γλώσσες','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Χωρίς όριο PHP','(server/FPM timeout still applies)'=>'(ο χρόνος αναμονής διακομιστή/FPM εξακολουθεί να ισχύει)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Η μετάφραση AI και η μαζική ανάλυση ενδέχεται να διαρκέσουν. Συνιστάται 120 δευτερόλεπτα ή περισσότερο.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'Ρύθμιση AI','(active)'=>'(ενεργό)','Configured'=>'Ρυθμίστηκε','No key'=>'Χωρίς κλειδί','— AI features are disabled.'=>'— Οι δυνατότητες AI είναι απενεργοποιημένες.','Add key →'=>'Προσθήκη κλειδιού →','Light model'=>'Ελαφρύ μοντέλο','Quality model'=>'Μοντέλο ποιότητας','Active preset'=>'Ενεργό προεπιλογή','Daily quota'=>'Ημερήσιο όριο','Unlimited'=>'Απεριόριστο','requests / day'=>'αιτήματα / ημέρα','Permalink Structure'=>'Δομή μόνιμου συνδέσμου','Permalink structure is compatible with Lingua Forge path routing.'=>'Η δομή μόνιμου συνδέσμου είναι συμβατή με τη δρομολόγηση διαδρομής του Lingua Forge.','Plain permalinks are not supported.'=>'Οι απλοί μόνιμοι σύνδεσμοι δεν υποστηρίζονται.','Path routing requires a post-name based permalink structure. Change it in'=>'Η δρομολόγηση διαδρομής απαιτεί δομή μόνιμου συνδέσμου βασισμένη σε όνομα ανάρτησης. Αλλάξτε το σε','Settings → Permalinks'=>'Ρυθμίσεις → Μόνιμοι σύνδεσμοι','Numeric permalink structure is not supported.'=>'Η δομή μόνιμου συνδέσμου αριθμητικής μορφής δεν υποστηρίζεται.','Switch to a post-name based structure in'=>'Μεταβείτε σε δομή βασισμένη σε όνομα ανάρτησης στο','SEO Plugins'=>'Πρόσθετα SEO','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Δεν ανιχνεύθηκαν πρόσθετα SEO τρίτων. Το Lingua Forge χειρίζεται όλη την πολυγλωσσική SEO έξοδο.','Active: %s.'=>'Ενεργό: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Δείτε τις Ρυθμίσεις → SEO → Συμβατότητα για ολόκληρο τον πίνακα συμπεριφοράς ανά λειτουργία.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'Το WooCommerce δεν είναι ενεργό.','Shop'=>'Κατάστημα','Cart'=>'Καλάθι','Checkout'=>'Ολοκλήρωση αγοράς','My Account'=>'Ο λογαριασμός μου','WooCommerce version'=>'Έκδοση WooCommerce','Order storage'=>'Αποθήκευση παραγγελιών','High-Performance Order Storage (HPOS)'=>'Αποθήκευση παραγγελιών υψηλής απόδοσης (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Προσαρμοσμένοι πίνακες — τα φίλτρα μετα-περιεχομένου LF δεν επηρεάζουν τις παραγγελίες.','Shared / compatibility mode'=>'Κοινόχρηστη / λειτουργία συμβατότητας','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + συγχρονισμός CPT — μεταβατικό; τα φίλτρα μετα-περιεχομένου LF εφαρμόζονται σε αντίγραφο CPT.','Legacy post-based (CPT)'=>'Παλιό σύστημα βασισμένο σε ανάρτηση (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Παραγγελίες στα wp_posts — βεβαιωθείτε ότι το shop_order εξαιρείται από την δρομολόγηση LF.','WcPageBridge active'=>'Ενεργό WcPageBridge','Yes'=>'Ναι','No — WooCommerce integration class not loaded'=>'Δεν φορτώθηκε η κλάση ενσωμάτωσης WooCommerce','WooCommerce page translations'=>'Μεταφράσεις σελίδων WooCommerce','No secondary languages configured.'=>'Δεν έχουν ρυθμιστεί δευτερεύουσες γλώσσες.','Active Plugins'=>'Ενεργά πρόσθετα','No active plugins detected.'=>'Δεν ανιχνεύθηκαν ενεργά πρόσθετα.','Version'=>'Έκδοση','_lf_lang Coverage'=>'Κάλυψη _lf_lang','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Οι αναρτήσεις χωρίς _lf_lang είναι αόρατες σε κάθε φίλτρο γλώσσας του Lingua Forge. Αυτό μπορεί να συμβεί όταν το περιεχόμενο εισάγεται ή δημιουργείται πριν ενεργοποιηθεί το πρόσθετο.','All published posts have a _lf_lang value. No gaps detected.'=>'Όλες οι δημοσιευμένες αναρτήσεις έχουν τιμή _lf_lang. Δεν εντοπίστηκαν κενά.','Missing'=>'Απουσιάζει','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Αποκλείστε αυτόν τον τύπο ανάρτησης από την δρομολόγηση γλώσσας — οι αναρτήσεις του δεν θα εμφανίζονται πλέον εδώ ή δεν θα λαμβάνουν _lf_lang. Αυτό δεν μπορεί να αναιρεθεί αυτόματα.','Exclude from routing'=>'Αποκλεισμός από δρομολόγηση','excluded from routing'=>'εξαιρέθηκε από δρομολόγηση','Destructive action — read before proceeding'=>'Καταστροφική ενέργεια — διαβάστε πριν προχωρήσετε','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Επιδιόρθωση ετικετών σε κάθε δημοσίευση που μπορεί να δρομολογηθεί, με _lf_lang = %s. Οι δημοσιεύσεις σε τύπους δημοσιεύσεων που εξαιρούνται από δρομολόγηση δεν επηρεάζονται. Εκτελέστε μόνο μετά την εισαγωγή περιεχομένου ή κατά την αρχική ενεργοποίηση — μην το χρησιμοποιείτε ως εργαλείο μαζικής αναθέσεως γλώσσας.','Repair — assign _lf_lang = %s to all routable posts above'=>'Επιδιόρθωση — ανάθεση _lf_lang = %s σε όλες τις δρομολογήσιμες δημοσιεύσεις που αναφέρονται παραπάνω','Rewrite Rules'=>'Κανόνες επανεγγραφής','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Εγγραφές που ανήκουν στο LF και καταχωρούνται αυτήν τη στιγμή στο $wp_rewrite->extra_rules_top. Χρήσιμο για διάγνωση 404 ή συγκρούσεις δρομολόγησης. Αντιγράψτε αυτά όταν υποβάλετε αναφορά σφάλματος.','%d rule registered'=>'%d καταχωρημένος κανόνας' . "\0" . '%d καταχωρημένοι κανόνες','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Δεν βρέθηκαν κανόνες επανεγγραφής LF. Εκκαθαρίστε τους μόνιμους συνδέσμους αν αυτό είναι απροσδόκητο.','Debug Info'=>'Πληροφορίες αποσφαλμάτωσης','Copy and paste into a GitHub issue or support request.'=>'Αντιγράψτε και επικολλήστε σε ένα θέμα GitHub ή αίτημα υποστήριξης.','Copy system info'=>'Αντιγραφή πληροφοριών συστήματος','Copied!'=>'Αντιγράφηκε!','Repairing…'=>'Επισκευή σε εξέλιξη…','Repair failed.'=>'Η επισκευή απέτυχε.','Network error.'=>'Σφάλμα δικτύου.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Αποκλείστε αυτόν τον τύπο ανάρτησης από τη δρομολόγηση γλώσσας; Οι αναρτήσεις του δεν θα εμφανίζονται πλέον σε αυτήν τη λίστα ή δεν θα λαμβάνουν _lf_lang. Μπορείτε να το αναιρέσετε στις Ρυθμίσεις → Δρομολογητής → Εξαιρέσεις φίλτρου ερωτήματος.','Excluding…'=>'Εξαιρούνται…','Failed to save exclusion.'=>'Αποτυχία αποθήκευσης εξαίρεσης.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d ανάρτηση με ετικέτα _lf_lang = %2$s.' . "\0" . '%1$d αναρτήσεις με ετικέτα _lf_lang = %2$s.','Uninstall Behaviour'=>'Απεγκατάσταση Συμπεριφοράς','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Ελέγχει τι συμβαίνει όταν ένας διαχειριστής διαγράφει το πρόσθετο από τα Πρόσθετα → Εγκατεστημένα πρόσθετα → Διαγραφή. Οι ρυθμίσεις και οι cache AI διαγράφονται πάντα. Οι αναθέσεις γλωσσών και οι σχέσεις μετάφρασης διατηρούνται από προεπιλογή ώστε μια τυχαία απεγκατάσταση ή επανεγκατάσταση να συνεχίσει από εκεί που σταμάτησε.','Uninstall setting saved.'=>'Αποθηκεύτηκε η ρύθμιση απεγκατάστασης.','Delete content data on uninstall'=>'Διαγραφή δεδομένων περιεχομένου κατά την απεγκατάσταση','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Επίσης διαγραφή αναθέσεων γλωσσών, σχέσεων μετάφρασης, μετα-περιγραφών, γλωσσάριου και μνήμης μετάφρασης όταν το πρόσθετο απεγκαθίσταται','Warning:'=>'Προειδοποίηση:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Εάν επιλεγεί, η απεγκατάσταση του πρόσθετου θα διαγράψει οριστικά όλες τις αναθέσεις γλωσσών, σχέσεις μετάφρασης, μετα-περιγραφές, προεπιλογές σελίδων, το γλωσσάρι AI και τη μνήμη μετάφρασης για κάθε ανάρτηση σε αυτόν τον ιστότοπο. Αυτό δεν μπορεί να αναιρεθεί. Αφήστε το ανεπιλεγμένο εκτός αν αφαιρείτε πλήρως την πολύγλωσση υποστήριξη από τον ιστότοπο.','Save Uninstall Setting'=>'Αποθήκευση ρύθμισης απεγκατάστασης','Today'=>'Σήμερα','Last 7 days'=>'Τελευταία 7 ημέρες','Last 30 days'=>'Τελευταία 30 ημέρες','All time'=>'Όλο το χρόνο','AI Usage'=>'Χρήση AI','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Η κατανάλωση tokens καταγράφεται ανά λειτουργία, πάροχο και μοντέλο. Καταγράφεται σε κάθε επιτυχημένη κλήση AI; οι δοκιμές σύνδεσης εξαιρούνται ώστε να μην επηρεάζουν τα συνολικά.','Check your account, billing, or remaining credits directly on the provider console:'=>'Ελέγξτε τον λογαριασμό σας, την χρέωση ή τα υπόλοιπα πιστώσεων απευθείας στην κονσόλα του παρόχου:','Anthropic Console'=>'Κονσόλα Anthropic','OpenAI Platform'=>'Πλατφόρμα OpenAI','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Δεν έχει καταγραφεί ακόμη χρήση AI. Μόλις ένας επεξεργαστής εκτελέσει μια μετάφραση, δημιουργήσει μια μετα-περιγραφή ή χρησιμοποιήσει οποιαδήποτε άλλη λειτουργία AI, τα σύνολα θα εμφανιστούν εδώ.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Δεν έχει καταγραφεί χρήση AI στο επιλεγμένο παράθυρο (%s). Επιλέξτε ευρύτερο εύρος παραπάνω.','Provider'=>'Πάροχος','Model'=>'Μοντέλο','Requests'=>'Αιτήματα','Input tokens'=>'Εισαγωγικά tokens','Output tokens'=>'Εξαγωγικά tokens','Total tokens'=>'Σύνολο tokens','Total'=>'Σύνολο','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Η Lingua Forge προσθέτει ιδιότητες Open Graph ειδικές για WooCommerce στις σελίδες προϊόντων ώστε η κοινή χρήση ενός URL προϊόντος στο Facebook, Pinterest και παρόμοιες πλατφόρμες να εμφανίζει τον σωστό τύπο προϊόντος, τιμή και διαθεσιμότητα.','WooCommerce SEO settings saved.'=>'Οι ρυθμίσεις SEO WooCommerce αποθηκεύτηκαν.','Product Open Graph'=>'Open Graph Προϊόν','Add WooCommerce product tags to Open Graph output'=>'Προσθέστε ετικέτες προϊόντων WooCommerce στην έξοδο Open Graph','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Όταν ενεργοποιείται, το Lingua Forge παράγει τις ακόλουθες πρόσθετες μετα-ετικέτες στις σελίδες προϊόντων: og:type=product, og:price:amount, og:price:currency, og:availability, και τα αντίστοιχα namespace product που χρησιμοποιούνται από το Facebook Catalog.','Tags emitted'=>'Ετικέτες που εκπέμπονται','Tag'=>'Ετικέτα','Value source'=>'Πηγή τιμής','"product" (replaces "article")'=>'"προϊόν" (αντικαθιστά "άρθρο")','WooCommerce product price'=>'Τιμή προϊόντος WooCommerce','WooCommerce store currency'=>'Νόμισμα καταστήματος WooCommerce','instock / oos / pending from WC stock status'=>'σε απόθεμα / εκτός αποθέματος / σε αναμονή από την κατάσταση αποθέματος του WC','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Η τιμή και η διαθεσιμότητα αντανακλούν πάντα το προϊόν της πηγής (μοναδικό μοντέλο αποθέματος). Οι ετικέτες εμφανίζονται μόνο όταν το module Open Graph του LF είναι ρυθμισμένο σε "Πλήρες" ή "Αυτόματο" χωρίς ανιχνευμένο συγκρουόμενο plugin SEO.','Save WooCommerce SEO Settings'=>'Αποθήκευση ρυθμίσεων SEO WooCommerce','AI Provider'=>'Πάροχος AI','AI Usage & Cache'=>'Χρήση & Cache AI','API Keys'=>'Κλειδιά API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Τα κλειδιά είναι κρυπτογραφημένα με AES-256-CBC πριν αποθηκευτούν στη βάση δεδομένων του WordPress. Το μυστικό κρυπτογράφησης προέρχεται από τα salts αυθεντικοποίησης του WordPress (wp-config.php), έτσι τα κείμενα σε απλό κείμενο ποτέ δεν έρχονται σε επαφή με τη βάση δεδομένων.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'Τα διαπιστευτήρια API διαχειρίζονται από το WordPress στο %s. Κανένα κλειδί δεν αποθηκεύεται από το Lingua Forge.','Settings → Connectors'=>'Ρυθμίσεις → Σύνδεσμοι','API Key'=>'Κλειδί API','Paste your API key…'=>'Επικολλήστε το κλειδί API σας…','✓ Configured'=>'✓ Διαμορφωμένο','✗ Not configured'=>'✗ Μη διαμορφωμένο','Test connection'=>'Δοκιμή σύνδεσης','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Αφήστε κενό για να διατηρήσετε το υπάρχον κλειδί. Εισάγετε μια νέα τιμή για να το αντικαταστήσετε.','Remove stored key'=>'Αφαίρεση αποθηκευμένου κλειδιού','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Αυτό το κλειδί παρέχεται αυτήν τη στιγμή από έναν διακομιστή %s και δεν μπορεί να αφαιρεθεί εδώ. Εισάγετε ένα νέο κλειδί παραπάνω για να το αντικαταστήσετε με μια τιμή βάσης δεδομένων.','environment variable'=>'μεταβλητή περιβάλλοντος','PHP constant'=>'σταθερά PHP','Alternative (server-side):'=>'Εναλλακτικά (διακομιστής-πλευρά):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Μπορείτε επίσης να ορίσετε κλειδιά ως σταθερές ή μεταβλητές περιβάλλοντος (π.χ. στο wp-config.php). Αυτές οι πηγές χρησιμοποιούνται αυτόματα ως εφεδρική επιλογή όταν δεν αποθηκεύεται κλειδί βάσης δεδομένων.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Για να χρησιμοποιήσετε ένα προσαρμοσμένο μυστικό κρυπτογράφησης (αντί της προεπιλεγμένης τιμής wp_salt), προσθέστε το αυτό στο wp-config.php:','Unknown provider.'=>'Άγνωστος πάροχος.','No API key configured for this provider.'=>'Δεν έχει διαμορφωθεί κλειδί API για αυτόν τον πάροχο.','Could not instantiate the provider.'=>'Δεν ήταν δυνατή η δημιουργία του παρόχου.','Provider returned no response. Check the WordPress error log for details.'=>'Ο πάροχος δεν έδωσε απάντηση. Ελέγξτε το αρχείο καταγραφής σφαλμάτων του WordPress για λεπτομέρειες.','Enter a model identifier to test.'=>'Εισαγάγετε ένα αναγνωριστικό μοντέλου για δοκιμή.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Δεν βρέθηκε δημοσιευμένη ανάρτηση ή σελίδα για δοκιμή — δημοσιεύστε πρώτα κάποιο περιεχόμενο, ή δοκιμάστε απευθείας τη Γρήγορη Μετάφραση.','(untitled)'=>'(χωρίς τίτλο)','Prompt template not found.'=>'Πρότυπο προτροπής δεν βρέθηκε.','Translation failed. Please try again.'=>'Η μετάφραση απέτυχε. Δοκιμάστε ξανά.','The sample post has no visible text content to translate.'=>'Η δείγμα ανάρτηση δεν έχει ορατό περιεχόμενο κειμένου για μετάφραση.','Chunk prompt template not found.'=>'Πρότυπο προτροπής τμήματος δεν βρέθηκε.','Model returned no response. Check the WordPress error log for details.'=>'Το μοντέλο δεν επέστρεψε απάντηση. Ελέγξτε το αρχείο σφάλματος του WordPress για λεπτομέρειες.','Behavior'=>'Συμπεριφορά','Block Editor'=>'Επεξεργαστής Μπλοκ','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Το Lingua Forge περιορίζει δύο λειτουργίες του Gutenberg από προεπιλογή για να διατηρεί συνεπή τη συμπεριφορά της επιμέλειας σε όλες τις γλώσσες. Επιλέξτε εδώ όταν χρειάζεστε πλήρεις δυνατότητες Gutenberg / FSE.','Block locking'=>'Κλείδωμα μπλοκ','Allow editors to lock individual blocks'=>'Επιτρέψτε στους επιμελητές να κλειδώνουν μεμονωμένα μπλοκ','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ενεργοποιεί ξανά το canLockBlocks του Gutenberg. Χρησιμότητα για πρότυπα επιμέλειας που πρέπει να αποτρέπουν τους συνεισφέροντες από τη μετακίνηση ή διαγραφή συγκεκριμένων μπλοκ.','Template mode'=>'Λειτουργία προτύπου','Allow Gutenberg template-editing mode on post screens'=>'Επιτρέψτε τη λειτουργία επεξεργασίας προτύπων Gutenberg στις οθόνες δημοσιεύσεων','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ενεργοποιεί ξανά το supportsTemplateMode. Βασικό για τις ροές εργασίας Full-Site-Editing όπου οι υπεροχές προτύπων σε επίπεδο δημοσίευσης είναι σκόπιμες.','Compliance Preset'=>'Προεπιλογή Συμμόρφωσης','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Λειτουργία αυστηρής διατήρησης για νομικό, κανονιστικό, ιατρικό ή τεχνικό περιεχόμενο. Όταν είναι ενεργό, κάθε λειτουργία AI χρησιμοποιεί χαμηλή θερμοκρασία δειγματοληψίας και προσθέτει το προσάρτημα παρακάτω στην προτροπή του συστήματος — η ορολογία, οι αριθμοί άρθρων, οι μονάδες, τα ονόματα εμπορικών σημάτων και η κανονιστική γλώσσα διατηρούνται αυτούσια και όχι παραφρασμένα.','Global AI preset'=>'Παγκόσμια προεπιλογή AI','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ανά λειτουργία','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ορίζει τη προεπιλεγμένη συμπεριφορά AI για όλες τις λειτουργίες σε ολόκληρο τον ιστότοπο. Τα μεμονωμένα δημοσιεύματα μπορούν να το παρακάμψουν για Μετάφραση και Δημιουργία Περιεχομένου μέσω του μετα-κουτιού Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Η Standard χρησιμοποιεί τη δική της ρυθμισμένη θερμοκρασία κάθε λειτουργίας: Μετάφραση T=0.2 (ακριβής), Γρήγορη Μετάφραση T=0.4, Δημιουργία Περιεχομένου T=0.6 (δημιουργική). Οι άλλες προεπιλογές εφαρμόζουν μια σταθερή θερμοκρασία σε όλες τις λειτουργίες.','Technical / Scientific instructions'=>'Τεχνικές / Επιστημονικές οδηγίες','Legal / Compliance instructions'=>'Νομικές / Συμμόρφωση οδηγίες','Creative / Marketing instructions'=>'Δημιουργικές / Μάρκετινγκ οδηγίες','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Αφήστε κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή. Η διαγραφή μιας αποθηκευμένης υπεροχής επαναφέρει την προεπιλογή στην επόμενη αποθήκευση.','View built-in default'=>'Προβολή ενσωματωμένης προεπιλογής','Automatic Translation Backfill'=>'Αυτόματη Επιπλήρωση Μετάφρασης','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Σαρώνει περιοδικά αναρτήσεις που λείπει μετάφραση σε μια ενεργή γλώσσα και θέτει σε ουρά μια μετάφραση AI για κάθε χάσμα που βρέθηκε — την ίδια ανάκαμψη που μπορείτε ήδη να ενεργοποιήσετε χειροκίνητα μέσω "Μετάφραση που λείπει" ή τις εντολές WP-CLI missing_translations/fill_translations, εκτελούμενη αυτόματα μία φορά ανά ώρα.','Automatic backfill'=>'Αυτόματη επιπλήρωση','Automatically translate posts missing a language version'=>'Μεταφράστε αυτόματα αναρτήσεις που λείπει μια έκδοση γλώσσας','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Απενεργοποιημένο προεπιλογή. Αυτό το χαρακτηριστικό κάνει αιτήματα προς τον AI παρέχοντα — και δαπανά το σχετικό κόστος API — αυτόματα και στο παρασκήνιο, χωρίς επιβεβαίωση ανά αίτημα, για κάθε δημοσιευμένη ανάρτηση που δεν βρέθηκε χωρίς μετάφραση σε ενεργή γλώσσα. Ενεργοποιήστε αυτό μόνο αν θέλετε κάθε κενό περιεχομένου να μεταφραστεί χωρίς επίβλεψη· διαφορετικά χρησιμοποιήστε "Μετάφραση που λείπει" ή τις εντολές WP-CLI για μετάφραση σύμφωνα με το δικό σας πρόγραμμα.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'Τα προϊόντα και παραλλαγές WooCommerce δεν περιλαμβάνονται ποτέ, ανεξάρτητα από αυτήν τη ρύθμιση. Μια ολοκλήρωση μπορεί επίσης να αποκλείσει συγκεκριμένους τύπους ανάρτησης μέσω του φίλτρου linguaforge_cpt_create_allowed.','Comment Translation'=>'Μετάφραση Σχολίου','Mirrors an approved comment onto every language version of the post it belongs to, translated, as a real comment on each sibling page. Off by default.'=>'Αντιγράφει ένα εγκεκριμένο σχόλιο σε κάθε γλωσσική έκδοση της ανάρτησης στην οποία ανήκει, μεταφρασμένο, ως πραγματικό σχόλιο σε κάθε αδελφική σελίδα. Απενεργοποιημένο από προεπιλογή.','Comment translation'=>'Μετάφραση σχολίου','Enable comment translation'=>'Ενεργοποίηση μετάφρασης σχολίου','Off by default. This feature makes AI provider requests — and spends the associated API cost — for approved comments on any post that has translated language versions. WooCommerce product reviews are never included; they already share one review pool across languages.'=>'Απενεργοποιημένο από προεπιλογή. Αυτή η λειτουργία πραγματοποιεί αιτήματα στον πάροχο AI — και ξοδεύει το σχετικό κόστος API — για εγκεκριμένα σχόλια σε οποιαδήποτε ανάρτηση έχει μεταφρασμένες γλωσσικές εκδόσεις. Οι κριτικές προϊόντων WooCommerce δεν περιλαμβάνονται ποτέ, καθώς μοιράζονται ήδη μία δεξαμενή κριτικών σε όλες τις γλείες.','Translation trigger'=>'Ενεργοποίηση μετάφρασης','Manual — translate only via the Comments screen action'=>'Χειροκίνητα — μεταφράστε μόνο μέσω της ενέργειας στην οθόνη Σχόλια','Automatic — translate every comment as soon as it\'s approved'=>'Αυτόματα — μεταφράστε κάθε σχόλιο μόλις εγκριθεί','Manual (default) queues nothing automatically — use the "Translate missing" bulk action on the Comments screen on your own schedule. Automatic queues a translation the moment a comment is approved (or arrives already-approved), which can spend API calls on comments a moderator was about to reject if there\'s a large held-for-moderation backlog.'=>'Χειροκίνητα (προεπιλογή) δεν βάζει τίποτα στην ουρά αυτόματα — χρησιμοποιήστε τη μαζική ενέργεια "Μετάφραση που λείπει" στην οθόνη Σχόλια κατά το πρόγραμμα σας. Αυτόματα τοποθετεί μία μετάφραση στην ουρά τη στιγμή που ένα σχόλιο εγκρίνεται (ή φτάνει ήδη εγκεκριμένο), γεγονός που μπορεί να ξοδέψει κλήσεις API σε σχόλια που ένας διαχειριστής επρόκειτο να απορρίψει αν υπάρχει μεγάλη εκκρεμότητα ελέγχου.','Max nested-reply depth'=>'Μέγιστο βάθος εσωτερικής απάντησης','How many levels of nested replies "Translate missing" will walk and translate in one pass, counting the original top-level comment as level 0. Default 2 covers the original comment plus replies and replies-to-replies. Bounds AI spend on deep threads — anything nested deeper isn\'t backfilled until this is raised or a further pass runs.'=>'Πόσες επίπεδα εσωτερικών απαντήσεων θα διασχίσει και θα μεταφράσει η "Μετάφραση που λείπει" σε μία διαδικασία, υπολογίζοντας το αρχικό σχόλιο ανώτερου επιπέδου ως επίπεδο 0. Η προεπιλογή 2 καλύπτει το αρχικό σχόλιο καθώς και απαντήσεις και απαντήσεις σε απαντήσεις. Περιορίζει την κατανάλωση AI σε βαθιά νήματα — οτιδήποτε είναι εσωτερικά βαθύτερο δεν συμπληρώνεται μέχρι αυτό να αυξηθεί ή να εκτελεστεί περαιτέρω διαδικασία.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Το κουμπί "Συγχρονισμός" στη στήλη Lang της λίστας ανάρτησης μεταφράζει ξανά μια ανάρτηση σε κάθε άλλη γλώσσα, συμπεριλαμβανομένης της κύριας/πηγής ανάρτησης όταν εκτελείται από μια μετάφραση. Αυτή η κατεύθυνση οπισθομετάφρασης είναι περιορισμένη προεπιλογή για κάθε τύπο ανάρτησης. (Τα προϊόντα WooCommerce και οι παραλλαγές τους έχουν τη δική τους ξεχωριστή ρύθμιση παρακάτω — αυτή δεν τα επηρεάζει.)','Secondary-language Sync'=>'Συγχρονισμός δευτερεύουσας γλώσσας','Allow "Sync" on a translated post to overwrite the primary post'=>'Επιτρέψτε "Συγχρονισμός" σε μια μεταφρασμένη ανάρτηση να αντικαταστήσει την κύρια ανάρτηση','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Απενεργοποιημένο προεπιλογή: το κλικ σε "Συγχρονισμός" σε μια μετάφραση απαγορεύεται από την αντικατάσταση της κύριας ανάρτησης. Ο συγχρονισμός ΑΠΟ την κύρια ανάρτηση σε κάθε μετάφραση είναι πάντα επιτρεπτός ανεξάρτητα από αυτήν τη ρύθμιση. Ενεργοποιήστε αυτό μόνο αν θέλετε ένα προϊόν μετάφρασης να μπορεί να γίνει το νέο περιεχόμενο πηγής.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Το κύριο προϊόν γλώσσας είναι η λειτουργική αρχή αναφοράς του WooCommerce για την τιμή, SKU και απόθεμα, τα οποία παρέχονται πάντα από αυτό ανεξάρτητα από την γλώσσα που προβάλλει ένας αγοραστής. Αυτή είναι μια ξεχωριστή, ανεξάρτητη ρύθμιση από τον γενικό περιορισμό "Συγχρονισμός" παραπάνω — η ενεργοποίηση του ενός δεν ενεργοποιεί το άλλο.','Allow "Sync" on a translated product to overwrite the primary product'=>'Επιτρέψτε "Συγχρονισμός" σε ένα μεταφρασμένο προϊόν να αντικαταστήσει το κύριο προϊόν','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Απενεργοποιημένο προεπιλογή: το κλικ σε "Συγχρονισμός" σε ένα μεταφρασμένο προϊόν WooCommerce αποκλείεται, καθώς θα οπισθομετάφραζε στον τίτλο, περιγραφή και απόσπασμα του κύριου προϊόντος. Ο συγχρονισμός ΑΠΟ το κύριο προϊόν σε κάθε μετάφραση είναι πάντα επιτρεπτός ανεξάρτητα από αυτήν τη ρύθμιση. Ενεργοποιήστε αυτό μόνο αν θέλετε ένα μεταφρασμένο προϊόν να μπορεί να γίνει το νέο περιεχόμενο πηγής.','General'=>'Γενικά','Light'=>'Ελαφρύ','Meta Description, Excerpt Generator, quick translate'=>'Μετα-περιγραφή, Γρήγορη δημιουργία αποσπάσματος, γρήγορη μετάφραση','Quality'=>'Ποιότητα','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Μετάφραση ολόκληρης σελίδας, Γεννήτρια περιεχομένου (ενδιάμεσοι μοντέλοι είναι πλήρως επαρκείς)','Active Provider'=>'Ενεργός Πάροχος','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Αυτή τη στιγμή κληρονομείται από τη σταθερά %s. Επιλέγοντας μια τιμή εδώ θα την αντικαταστήσει.','WordPress AI Client — requirements:'=>'Πελάτης AI του WordPress — απαιτήσεις:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Η μετάφραση ολόκληρης της σελίδας χρησιμοποιεί JSON-schema-περιορισμένη έξοδο. Αυτό απαιτεί την εγκατάσταση και ενεργοποίηση ενός πρόσθετου διασύνδεσης (όχι απλώς μια αποθηκευμένη API key στις Ρυθμίσεις → Συνδετήρες). Αν η μετάφραση αποτύχει, ελέγξτε το αρχείο καταγραφής σφαλμάτων PHP για το συγκεκριμένο σφάλμα, ή μεταβείτε σε έναν ενσωματωμένο πάροχο.','Manage your account, review usage, or top up credits:'=>'Διαχειριστείτε τον λογαριασμό σας, ελέγξτε τη χρήση ή προσθέστε πιστώσεις:','WordPress Connectors'=>'Συνδέσμοι WordPress','Models'=>'Μοντέλα','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Οι λειτουργίες ομαδοποιούνται σε δύο επίπεδα. Εισάγετε τον ακριβή αναγνωριστικό μοντέλου για κάθε επίπεδο και πάροχο. Αφήστε κενό ένα πεδίο για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειξη). Μόνο τα μοντέλα του ενεργού παρόχου καλούνται κατά την εκτέλεση — διαμορφώστε τα άλλα εκ των προτέρων αν σκοπεύετε να αλλάξετε.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Ξεκινήστε να πληκτρολογείτε σε οποιοδήποτε πεδίο για να δείτε προτάσεις μοντέλου, ή χρησιμοποιήστε τον πίνακα αναφοράς παρακάτω. Τα μοντέλα ποιότητας Light και mid-tier (Haiku, GPT-4o mini, Gemini Flash) είναι πλήρως επαρκή για μετάφραση και δημιουργία περιεχομένου — τα κορυφαία μοντέλα "max" προσθέτουν κόστος με ελάχιστο όφελος ποιότητας για δομημένο κείμενο.','active'=>'ενεργό','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Ο διαλογή επιλογής μοντέλου διαχειρίζεται από το WordPress στο %s — κανένα αναγνωριστικό μοντέλου δεν αποθηκεύεται από το Lingua Forge για αυτόν τον πάροχο.','overridden'=>'υπερβαλλόμενο','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Μεταφράζει ένα σύντομο δείγμα της πιο πρόσφατης δημοσιευμένης ανάρτησής σας με ακριβώς αυτό το μοντέλο — μια πραγματική, χρεωθείσα κλήση API.','Test model'=>'Δοκιμαστικό μοντέλο','Tip: to reset a model to the built-in default, clear the field and save.'=>'Συμβουλή: για να επαναφέρετε ένα μοντέλο στην ενσωματωμένη προεπιλογή, διαγράψτε το πεδίο και αποθηκεύστε.','Available models reference'=>'Αναφορά διαθέσιμων μοντέλων','Model ID'=>'ID μοντέλου','Name'=>'Όνομα','Tier'=>'Επίπεδο','Notes'=>'Σημειώσεις','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Αυτός ο κατάλογος ενημερώνεται με κάθε έκδοση του Lingua Forge. Η δοκιμή σύνδεσης στην καρτέλα API Keys επίσης λαμβάνει τη λίστα ζωντανών μοντέλων από τον πάροχο και ανανεώνει τις προτάσεις παραπάνω.','Glossary'=>'Γλωσσάρι','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Πίνακας ορολογίας που διαχειρίζεται ο χρήστης ανά ζεύγος γλωσσών. Οι καταχωρίσεις προστίθενται στην προτροπή συστήματος μετάφρασης, ώστε η ΤΝ να χρησιμοποιεί συνεπώς τους προτιμώμενους όρους — κρίσιμο για το λεξιλόγιο τομέα ("kWp", "PPA", "σημείο διασύνδεσης"), ονόματα εμπορικών σημάτων που δεν πρέπει να μεταφράζονται, και τυποποιημένη διατύπωση κανονισμών. Και τα δύο πεδία γλώσσας είναι προαιρετικά: αφήστε το "Πηγή γλώσσα" κενό για να εφαρμοστεί η καταχώριση ανεξάρτητα από τη γλώσσα από την οποία μεταφράζετε· αφήστε το "Στόχος γλώσσα" κενό για να το εφαρμόσετε σε όλες τις στοχευόμενες γλώσσες ταυτόχρονα.','Glossary entry added.'=>'Καταχώριση λεξικού προστέθηκε.','Glossary entry removed.'=>'Καταχώριση λεξικού αφαιρέθηκε.','Could not add entry: source term and target term are required.'=>'Αδυναμία προσθήκης καταχώρισης: απαιτούνται όρος πηγής και όρος στόχου.','Could not save the glossary entry.'=>'Αδυναμία αποθήκευσης της καταχώρισης λεξικού.','Source language'=>'Γλώσσα πηγής','— Any —'=>'— Οποιαδήποτε —','Target language'=>'Γλώσσα στόχου','— Any target —'=>'— Οποιαδήποτε στόχος —','Filter'=>'Φίλτρο','Reset'=>'Επαναφορά','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Δεν υπάρχουν καταχωρίσεις λεξικού που να ταιριάζουν με το τρέχον φίλτρο. Αφαιρέστε το φίλτρο για να δείτε όλες τις καταχωρίσεις ή προσθέστε μια νέα παρακάτω.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Δεν υπάρχουν ακόμα καταχωρίσεις λεξικού. Προσθέστε μία παρακάτω για να αρχίσετε να επιβάλλετε ορολογία στις μεταφράσεις.','Source term'=>'Όρος πηγής','Target term'=>'Όρος στόχου','Source lang'=>'Γλώσσα πηγής','Target lang'=>'Γλώσσα στόχου','any'=>'οποιαδήποτε','Delete this glossary entry?'=>'Να διαγραφεί αυτή η καταχώριση λεξικού;','Add new entry'=>'Προσθήκη νέας καταχώρισης','The phrase as it appears in the source text.'=>'Η φράση όπως εμφανίζεται στο πρωτότυπο κείμενο.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Πώς πρέπει να εμφανίζεται στη μετάφραση. Πληκτρολογήστε την ίδια τιμή με τον όρο πηγής για να την διατηρήσετε αυτούσια.','— Any source language —'=>'— Οποιαδήποτε πηγή —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Αφήστε κενό για ονόματα εμπορικών σημάτων και όρους που δεν σχετίζονται με γλώσσα και πρέπει να επιβάλλονται ανεξάρτητα από τη γλώσσα μεταφράσης.','— Any target language —'=>'— Οποιαδήποτε στόχος —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Αφήστε κενό για να εφαρμοστεί σε όλες τις στοχευόμενες γλώσσες — ιδανικό για ονόματα εμπορικών σημάτων, συντομογραφίες και όρους που πρέπει να διατηρούνται αυτούσιοι σε κάθε μετάφραση.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Προαιρετικό πλαίσιο για τους επεξεργαστές (π.χ. "ASIC = Εξειδικευμένο ολοκληρωμένο κύκλωμα εφαρμογής; διατηρείται στα Αγγλικά σε τεχνικά πλαίσια").','Add entry'=>'Προσθήκη καταχώρισης','Limits'=>'Όρια','Authors and above (edit_published_posts)'=>'Συγγραφείς και άνω (επεξεργασία_δημοσιευμένων_αναρτήσεων)','Contributors and above — default (edit_posts)'=>'Συνεισφέροντες και άνω — προεπιλογή (επεξεργασία_αναρτήσεων)','Editors and above (edit_others_posts)'=>'Επεξεργαστές και άνω (επεξεργασία_άλλων_αναρτήσεων)','Administrators only (manage_options)'=>'Μόνο διαχειριστές (διαχείριση_επιλογών)','AI Limits & Security'=>'Όρια AI & Ασφάλεια','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Περιορίστε τη χρήση AI που μπορεί να παράγει ο ιστότοπος και περιορίστε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν πληρωμένες κλήσεις AI. Βρίσκεται πάνω από το όριο ρυθμού ανά χρήστη (30 αιτήματα / λεπτό, σκληρά κωδικοποιημένο) που ήδη προστατεύει από ανεξέλεγκτες επαναλήψεις χρήστη.','Daily request limit'=>'Όριο ημερήσιων αιτημάτων','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Επίπεδο ορίου AI σε όλο τον ιστότοπο ανά UTC ημέρα (μετρά τόσο τις μεταφράσεις Toolbar όσο και τις αναθεωρήσεις μπλοκ). Η καταμέτρηση επαναφέρεται τα μεσάνυχτα UTC. Ορίστε το σε 0 για απενεργοποίηση του ορίου.','Minimum role'=>'Ελάχιστος ρόλος','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Η χαμηλότερη δυνατότητα WordPress που επιτρέπεται να ενεργοποιήσει λειτουργίες AI. Η αυστηροποίηση αυτού σε ιστότοπους με πολλούς συγγραφείς αποτρέπει τους Συμβάλλοντες ή δοκιμαστικούς λογαριασμούς από την εκτέλεση πληρωμένων κλήσεων AI. Παρακάμπτεται ανά λειτουργία μέσω του φίλτρου linguaforge_required_capability.','Translation Limits'=>'Όρια Μετάφρασης','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Ελέγξτε πόσο περιεχόμενο αποστέλλεται στην AI και πόσο μεγάλο μπορεί να είναι το απάντημα. Αφήστε ένα πεδίο κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειγμα). Αυξήστε αυτές τις τιμές αν μεγάλες σελίδες κόβονται, μειώστε τις για να μειώσετε το κόστος API.','Model tier'=>'Επίπεδο μοντέλου','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (προεπιλογή — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ελαφρύ (γρήγορο και οικονομικό — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Ποιο επίπεδο μοντέλου να χρησιμοποιήσετε για μετάφραση ολόκληρης σελίδας. Η ποιότητα χρησιμοποιεί το μοντέλο που έχει διαμορφωθεί στον πίνακα Μοντέλων και προτείνεται για ακριβή, μακροσκελή μετάφραση. Μεταβείτε σε Ελαφρύ μόνο αν η ταχύτητα ή το κόστος είναι προτεραιότητα και το περιεχόμενο είναι σύντομο.','Max output tokens'=>'Μέγιστοι tokens εξόδου','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Μέγιστος αριθμός tokens που μπορεί να παράγει η AI σε μια απάντηση μετάφρασης. Αν μια μετάφραση κόβεται σιωπηλά στο τέλος, αυξήστε αυτήν την τιμή. Προεπιλογή: 16.000.','Max input characters'=>'Μέγιστοι χαρακτήρες εισόδου','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Μέγιστος αριθμός χαρακτήρων του περιεχομένου της ανάρτησης που προωθείται στην ΤΝ. 0 σημαίνει χωρίς όριο — το πλήρες περιεχόμενο αποστέλλεται πάντα (συνιστάται). Ορίστε μια μη μηδενική τιμή μόνο αν ο πάροχός σας έχει στενό πλαίσιο συμφραζομένων. Μια προειδοποίηση γράφεται στο αρχείο καταγραφής σφαλμάτων PHP κάθε φορά που το περιεχόμενο περικόπτεται.','Quick Translation'=>'Γρήγορη Μετάφραση','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Η Γρήγορη Μετάφραση χρησιμοποιείται για λειτουργία αποσπάσματος/κομματιού — σύντομες περικοπές μεταφράζονται κατ\' απαίτηση από τη γραμμή εργαλείων, τον επεξεργαστή ή τα αναδυόμενα παράθυρα μπλοκ. Χρησιμοποιεί μια ξεχωριστή, ελαφρύτερη διαμόρφωση από τη μετάφραση σε πλήρη σελίδα για να διατηρεί τις απαντήσεις γρήγορες και οικονομικές.','Light (default — fast and cost-effective)'=>'Ελαφρύ (προεπιλογή — γρήγορο και οικονομικό)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Το επίπεδο Light χρησιμοποιεί το γρήγορο μοντέλο που διαμορφώνεται στον πίνακα Μοντέλων παραπάνω (προεπιλογή: Haiku / Flash). Μεταβείτε στην Ποιότητα αν χρειάζεστε την ίδια ακρίβεια μετάφρασης με τη λειτουργία πλήρους σελίδας για αποσπάσματα.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά γρήγορη μετάφραση. Προεπιλογή: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Μέγιστοι χαρακτήρες που γίνονται αποδεκτοί από το πεδίο εισόδου. Προεπιλογή: 8.000.','Content Generator'=>'Παραγωγός Περιεχομένου','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Ελέγχει τον προϋπολογισμό δείκτη και τα όρια εισόδου για τη λειτουργία Παραγωγέα Περιεχομένου ΤΝ. Αφήστε τα πεδία κενά για να χρησιμοποιήσετε τις ενσωματωμένες προεπιλογές.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά εκτέλεση δημιουργίας. Αυξήστε το αν τα πλήρη άρθρα κόβονται. Προεπιλογή: 8.192.','Max hints characters'=>'Μέγιστοι χαρακτήρες υποδείξεων','Maximum characters read from the Hints field. Default: 2 000.'=>'Μέγιστοι χαρακτήρες που διαβάζονται από το πεδίο Υποδείξεων. Προεπιλογή: 2.000.','Max context characters'=>'Μέγιστοι χαρακτήρες συμφραζομένων','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Μέγιστοι χαρακτήρες υπάρχοντος περιεχομένου ανάρτησης που περνιέται στην ΤΝ ως σπόρος συμφραζομένων όταν δεν παρέχονται Υποδείξεις. Προεπιλογή: 6.000.','Maintenance'=>'Συντήρηση','Router'=>'Δρομολογητής','Primary language saved.'=>'Αποθηκεύτηκε η κύρια γλώσσα.','Permalink rules flushed successfully.'=>'Οι κανόνες permalink εκκαθαρίστηκαν με επιτυχία.','Language uninstalled. %d post deleted.'=>'Η γλώσσα απεγκαταστάθηκε. %d ανάρτηση διαγράφηκε.' . "\0" . 'Η γλώσσα απεγκαταστάθηκε. %d αναρτήσεις διαγράφηκαν.','%d locale file removed.'=>'Το αρχείο τοπικής γλώσσας %d διαγράφηκε.' . "\0" . 'Τα αρχεία τοπικής γλώσσας %d διαγράφηκαν.','%d pattern translation removed.'=>'%d μετάφραση προτύπου αφαιρέθηκε.' . "\0" . '%d μεταφράσεις προτύπου αφαιρέθηκαν.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Δεν ήταν δυνατή η αυτόματη διαγραφή %d αρχείων τοπικής γλώσσας (ΟΡΙΖΕΙΤΑΙ το DISALLOW_FILE_MODS). Διαγράψτε το χειροκίνητα μέσω του διακομιστή σας ή WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Δεν ήταν δυνατή η αυτόματη διαγραφή %d αρχείων τοπικής γλώσσας (ΟΡΙΖΕΙΤΑΙ το DISALLOW_FILE_MODS). Διαγράψτε τα χειροκίνητα μέσω του διακομιστή σας ή WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Κύρια γλώσσα','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Η κύρια γλώσσα σερβίρεται πάντα στην ρίζα του ιστότοπού σας — χωρίς πρόθεμα URL στη διαδρομή σε λειτουργία μονοπατιού, χωρίς υποτομέα γλώσσας σε λειτουργία υποτομέα. Όλες οι άλλες γλώσσες χρησιμοποιούν είτε πρόθεμα διαδρομής /lang/ (π.χ. example.com/de/) είτε υποτομέα γλώσσας (π.χ. de.example.com), ανάλογα με τη ρύθμιση δομής URL παρακάτω.','Primary language'=>'Κύρια γλώσσα','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Μετά την αλλαγή της κύριας γλώσσας, εκκαθαρίστε τους permalinks (ενότητα παρακάτω) για να ενημερωθεί η δρομολόγηση URL.','Path prefix — example.com/de/'=>'Πρόθεμα διαδρομής — example.com/de/','Subdomain — de.example.com/'=>'Υποτομέας — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Ο τρόπος υποτομέα απαιτεί από τον διακομιστή σας να δείχνει όλους τους υποτομείς γλώσσας (π.χ. de.example.com) σε αυτήν την εγκατάσταση WordPress. Μετά την αλλαγή τρόπου, καθαρίστε τους κανόνες permalink και διαγράψτε τυχόν cache. Αν η αρχική URL περιλαμβάνει www (π.χ. www.example.com), χρησιμοποιήστε το φίλτρο lf_base_domain για να ορίσετε το απλό ανώτατο domain ώστε οι υποτομείς να κατασκευάζονται σωστά.','Browser language redirect'=>'Ανακατεύθυνση γλώσσας περιηγητή','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ανακατεύθυνση επισκεπτών στη προτιμώμενη γλώσσα τους βάσει της κεφαλίδας Accept-Language του περιηγητή','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Όταν ενεργοποιηθεί, οι επισκέπτες που επισκέπτονται για πρώτη φορά χωρίς cookie γλώσσας και χωρίς πρόθεμα γλώσσας στη διεύθυνση URL ανακατευθύνονται στην πιο κοντινή αντιστοιχισμένη έκδοση γλώσσας. Η ανακατεύθυνση παραλείπεται αν η προτιμώμενη γλώσσα του περιηγητή δεν είναι ανάμεσα στις ενεργές γλώσσες δρομολόγησης. Μόλις ένας επισκέπτης επιλέξει μια γλώσσα μέσω του διακόπτη, το cookie έχει προτεραιότητα και η κεφαλίδα του περιηγητή αγνοείται σε όλες τις μελλοντικές επισκέψεις.','Query Filter Exclusions'=>'Εξαιρέσεις φίλτρου ερωτήματος','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Το Lingua Forge περιορίζει τις δευτερεύουσες περιπτώσεις WP_Query ( widgets πλαϊνού μενού, μπλοκ προτύπων, αναζητήσεις πρόσθετων) στη ενεργή γλώσσα εισάγοντας ένα _lf_lang μετα-περιεχομένου περιορισμό. Οι τύποι ανάρτησης που αναφέρονται εδώ εξαιρούνται από αυτόν τον περιορισμό — τα ερωτήματα τους είναι πάντα χωρίς φίλτρα.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Το Contact Form 7 (wpcf7_contact_form), οι επαφές Flamingo και τα εισερχόμενα μηνύματα (flamingo_contact, flamingo_inbound), και η αποθήκευση συγχρονισμού πακέτου γλώσσας WordPress (wp_sync_storage) εξαιρούνται αυτόματα. Προσθέστε οποιοδήποτε άλλο τύπο δημοσίευσης τρίτου μέρους των οποίων το περιεχόμενο δεν πρέπει να φιλτράρεται γλώσσα, μία ανά γραμμή ή διαχωρισμένο με κόμμα.','Excluded post types'=>'Εξαιρούμενοι τύποι ανάρτησης','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Οι τύποι δημοσιεύσεων χωρίζονται με κόμμα ή νέα γραμμή. Οι αλλαγές ισχύουν αμέσως κατά την αποθήκευση — δεν απαιτείται εκκαθάριση permalink.','WooCommerce Integration'=>'Ενσωμάτωση WooCommerce','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Ελέγχει πώς το Lingua Forge ενσωματώνεται με την επεξεργασία παραγγελιών WooCommerce.','Order line item source mapping'=>'Χαρτογράφηση πηγής γραμμής παραγγελίας','Normalize order line item product IDs to the source-language product at checkout'=>'Κανονικοποιήστε τα αναγνωριστικά προϊόντων γραμμής παραγγελίας στην πηγή-γλώσσα κατά το checkout','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Όταν ενεργοποιείται (συνιστάται), το αναγνωριστικό προϊόντος που αποθηκεύεται σε κάθε γραμμή παραγγελίας WooCommerce ορίζεται στο προϊόν-πηγή. Αυτό διασφαλίζει ότι οι μετρήσεις total_sales, οι γραμμές εσόδων του WC Analytics και οι εξαγωγές τρίτων ERP αναφέρονται σε ένα αναγνωριστικό προϊόντος ανά SKU και όχι σε μία ανά έκδοση γλώσσας. Μειονέκτημα: τα links "Προβολή προϊόντος" σε email παραγγελίας και στον Λογαριασμό οδηγούν στη σελίδα της πηγής. Απενεργοποιήστε μόνο αν ένα συνδεδεμένο σύστημα βασίζεται σε μεταφρασμένα αναγνωριστικά προϊόντων στις παραγγελίες. Χρησιμοποιήστε το φίλτρο linguaforge_wc_order_item_source_mapping για υπεροχές ανά στοιχείο.','Save Router Settings'=>'Αποθήκευση Ρυθμίσεων Δρομολογητή','Flush Permalinks'=>'Καθαρισμός Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Αναγεννά τους κανόνες επαναγραφής του WordPress ώστε τα προθέματα URL, τα συγκεκριμένα για τη γλώσσα slug και οι ανακατατάξεις αρχείων να είναι συγχρονισμένα. Απαραίτητο μετά την αλλαγή της κύριας γλώσσας ή την προσθήκη νέας υποστήριξης γλώσσας.','Flush Permalink Rules'=>'Καθαρισμός Κανόνων Permalink','Active Languages'=>'Ενεργές Γλώσσες','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Οι γλώσσες που είναι γνωστές στον δρομολογητή (προερχόμενες από τα εγκατεστημένα πακέτα locale του WordPress συν την κύρια γλώσσα). Εγκαταστήστε πρόσθετα πακέτα γλώσσας στην παρακάτω ενότητα για να κάνετε περισσότερες γλώσσες διαθέσιμες για δρομολόγηση και μετάφραση.','%d locale pack installed.'=>'%d πακέτο locale εγκατεστημένο.' . "\0" . '%d πακέτα locale εγκατεστημένα.','Install a Language'=>'Εγκατάσταση Γλώσσας','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Κατεβάστε και εγκαταστήστε ένα πακέτο γλώσσας πυρήνα WordPress απευθείας από το WordPress.org. Μόλις εγκατασταθεί, η locale γίνεται διαθέσιμη για δρομολόγηση URL και τη ροή εργασίας μετάφρασης AI. Η λίστα των διαθέσιμων γλωσσών λαμβάνεται κατ\' απαίτηση — κάντε κλικ στο κουμπί παρακάτω για φόρτωση.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή. Η σταθερά DISALLOW_FILE_MODS ορίζεται στο wp-config.php. Εγκαταστήστε χειροκίνητα πακέτα γλώσσας μέσω WP-CLI: wp language core install de_DE','Load available languages'=>'Φόρτωση διαθέσιμων γλωσσών','— select a language —'=>'— επιλέξτε μια γλώσσα —','Install'=>'Εγκατάσταση','Language Setup'=>'Ρύθμιση Γλώσσας','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Δεν έχουν διαμορφωθεί δευτερεύουσες γλώσσες. Εγκαταστήστε ένα πακέτο γλώσσας παραπάνω για να ενεργοποιήσετε το πλαίσιο προτύπων.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Επιλέξτε μια γλώσσα για να διαχειριστείτε τα πρότυπα FSE, τα μέρη προτύπων και τα μενού πλοήγησης.','Recreate All Languages'=>'Δημιουργία όλων των γλωσσών εκ νέου','Recreate All Languages (Templates Only)'=>'Δημιουργία όλων των γλωσσών εκ νέου (Μόνο πρότυπα)','Recreate All Languages (Template Parts Only)'=>'Δημιουργία όλων των γλωσσών εκ νέου (Μόνο τμήματα προτύπων)','Cancel'=>'Ακύρωση','Repair Template Metadata'=>'Επιδιόρθωση μεταδεδομένων προτύπου','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Επιδιορθώνει το namespace του Site Editor και την ετικέτα _lf_lang σε όλα τα πρότυπα FSE που έχουν δημιουργηθεί με το LF και αποθηκεύονται στη βάση δεδομένων. Εκτελέστε αυτό μία φορά μετά την ενημέρωση από προηγούμενη έκδοση του Lingua Forge — μετακινεί τα πρότυπα που προέρχονται από το WooCommerce από την ομάδα ενεργού θέματος στην ομάδα WooCommerce στον Site Editor, και διασφαλίζει ότι όλα τα δημιουργημένα πρότυπα είναι ανιχνεύσιμα από τις αναφορές κάλυψης.','Repair template metadata'=>'Επιδιόρθωση μεταδεδομένων προτύπου','Request failed.'=>'Το αίτημα απέτυχε.','Forbidden'=>'Απαγορεύεται','Danger Zone'=>'Ζώνη Κινδύνου','Uninstall %s'=>'Απεγκατάσταση %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Οριστικά διαγράφει όλα τα πρότυπα, μέρη προτύπων, μοτίβα, μενού πλοήγησης, αναρτήσεις, σελίδες, προσαρμοσμένους τύπους αναρτήσεων, προϊόντα και παραλλαγές προϊόντων που σχετίζονται με αυτή τη γλώσσα. Ακόμα και διαγράφει τα αρχεία πακέτου locale του WordPress ώστε αυτή η γλώσσα να μην εμφανίζεται πλέον στον δρομολογητή. Αυτή η ενέργεια δεν μπορεί να αναιρεθεί.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Αυτή η γλώσσα ταιριάζει με την τοπική ρύθμιση του WordPress και δεν μπορεί να απεγκατασταθεί.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Οριστικά απεγκαθιστάτε το %s; Αυτό θα διαγράψει όλο το μεταφρασμένο περιεχόμενο για αυτή τη γλώσσα και δεν μπορεί να αναιρεθεί.','Invalid language code.'=>'Μη έγκυρος κωδικός γλώσσας.','This language is protected and cannot be uninstalled.'=>'Αυτή η γλώσσα προστατεύεται και δεν μπορεί να απεγκατασταθεί.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή (ορίζεται το DISALLOW_FILE_MODS).','Invalid locale code.'=>'Μη έγκυρος κωδικός locale.','Language %s installed successfully.'=>'Η γλώσσα %s εγκαταστάθηκε με επιτυχία.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Η εγκατάσταση πακέτου γλώσσας απέτυχε. Η γλώσσα μπορεί ήδη να είναι εγκατεστημένη, ο κωδικός locale μπορεί να είναι λανθασμένος ή ο διακομιστής σας να εμποδίζει την εγγραφή αρχείων.','Navigations'=>'Πλοηγήσεις','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Η μετάφραση πλοήγησης απαιτεί ενεργό πάροχο AI. Διαμορφώστε ένα κλειδί API στην καρτέλα Κλειδιά API.','Navigation'=>'Πλοήγηση','Re-translate'=>'Επαναμετάφραση','CPT Block Patterns'=>'Μοτίβα μπλοκ CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Μοτίβα μπλοκ που έχουν καταχωρηθεί για προσαρμοσμένους τύπους ανάρτησης. Χρησιμοποιήστε το κουμπί Μετάφραση για να δημιουργήσετε μια παραλλαγή γλώσσας. Το μεταφρασμένο περιεχόμενο αποθηκεύεται εδώ και μπορεί να αντιγραφεί σε οποιαδήποτε ανάρτηση CPT από τον εισαγωγέα μοτίβων επεξεργαστή μπλοκ ή να χρησιμοποιηθεί ως σημείο εκκίνησης για ένα Συγχρονισμένο Μοτίβο (Επαναχρησιμοποιήσιμο Μπλοκ).','Pattern'=>'Μοτίβο','Post Types'=>'Τύποι Ανάρτησης','✓ Translation saved'=>'✓ Μετάφραση αποθηκευμένη','View'=>'Προβολή','Template Parts'=>'Μέρη προτύπων','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Αντίγραφα συγκεκριμένων γλωσσών των μερών προτύπων του θέματος. Μόλις δημιουργηθούν, τα πρότυπα ενημερώνονται ώστε να αναφέρονται στο μέρος που είναι συγκεκριμένο για τη γλώσσα.','Re-create all'=>'Δημιουργία όλων εκ νέου','Translate all'=>'Μετάφραση όλων','Fix all links'=>'Επιδιόρθωση όλων των συνδέσμων','Fix all navs'=>'Επιδιόρθωση όλων των πλοήγησης','Part'=>'Μέρος','Status / Actions'=>'Κατάσταση / Ενέργειες','Create'=>'Δημιουργία','Templates'=>'Πρότυπα','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Τα πρότυπα FSE που έχουν δημιουργηθεί από το ενεργό θέμα. Δημιουργήστε και προσαρμόστε στο Επεξεργαστή Ιστοσελίδας.','Create missing'=>'Δημιουργία ελλείποντος','Fix all parts'=>'Επιδιόρθωση όλων των μερών','SEO'=>'SEO','Multilingual SEO'=>'Πολυγλωσσικό SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Ρύθμιση hreflang, Open Graph, Schema.org, χάρτες ιστοτόπου και κοινωνική κοινοποίηση για κάθε γλώσσα στον ιστότοπό σας. Κάθε τμήμα παρακάτω χειρίζεται μια πτυχή του πολυγλωσσικού SEO.','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Schema.org'=>'Schema.org','Sitemap'=>'Χάρτης ιστότοπου','Analysis'=>'Ανάλυση','Compatibility'=>'Συμβατότητα','System'=>'Σύστημα','Overview'=>'Επισκόπηση','Lingua Forge Settings'=>'Ρυθμίσεις Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Το Lingua Forge προσθέτει πολύγλωσση δρομολόγηση, μετάφραση με AI, ετικέτες SEO hreflang και διακόπτη γλώσσας στον ιστότοπό σας WordPress.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Χρησιμοποιήστε τις καρτέλες στην κορυφή αυτής της σελίδας για να διαμορφώσετε κάθε περιοχή. Οι αλλαγές στην καρτέλα δρομολογητή λαμβάνουν άμεσα effect; οι αλλαγές στα κλειδιά AI και τις ρυθμίσεις μοντέλου εφαρμόζονται στην επόμενη αίτηση AI.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Μετά την αλλαγή των ρυθμίσεων δομής URL (πρόθεμα διαδρομής ↔ υποτομέας), επισκεφθείτε πάντα τις Ρυθμίσεις → Μόνιμοι σύνδεσμοι και κάντε κλικ στην Αποθήκευση αλλαγών για να εκκαθαρίσετε τους κανόνες ανακατεύθυνσης.','AI Provider Tab'=>'Καρτέλα Πάροχος AI','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Υποστηριζόμενοι πάροχοι: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Επιλέξτε τον ενεργό πάροχο από το αναπτυσσόμενο μενού — μόνο ένας πάροχος χρησιμοποιείται κάθε φορά. Εισάγετε ένα κλειδί API για αυτόν τον πάροχο για να ενεργοποιήσετε τις λειτουργίες AI.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Τα κλειδιά είναι κρυπτογραφημένα σε κατάσταση αναμονής χρησιμοποιώντας AES-256-GCM με ένα μυστικό που είναι συγκεκριμένο για τον ιστότοπο (LINGUAFORGE_SECRET). Μην μοιράζεστε εξαγωγές βάσεων δεδομένων χωρίς πρώτα να περιστρέψετε το μυστικό.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Οι λειτουργίες AI είναι προαιρετικές. Η δρομολόγηση γλωσσών, το hreflang, ο διακόπτης γλώσσας και το σύστημα ομάδας μετάφρασης λειτουργούν όλα χωρίς διαμορφωμένο πάροχο.','Model tiers'=>'Επίπεδα μοντέλου','Lingua Forge uses two model tiers per provider:'=>'Το Lingua Forge χρησιμοποιεί δύο επίπεδα μοντέλων ανά πάροχο:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Φωτεινό: χρησιμοποιείται για μετα-περιγραφές και δημιουργία αποσπασμάτων — γρήγορο, χαμηλό κόστος.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ποιότητα: χρησιμοποιείται για μετάφραση ανάρτησης και δημιουργία περιεχομένου — υψηλότερη ποιότητα, υψηλότερο κόστος.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Αφήστε ένα πεδίο μοντέλου κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή για αυτό το επίπεδο. Το κείμενο υπόδειξης δείχνει ποιο μοντέλο θα χρησιμοποιηθεί.','Translation Limits & Behavior'=>'Όρια και συμπεριφορά μετάφρασης','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Όρια μετάφρασης: ελέγξτε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν τη μετάφραση AI και ορίστε έναν μηνιαίο προϋπολογισμό tokens. Η υπέρβαση του προϋπολογισμού διακόπτει τις κλήσεις AI μέχρι την επαναφορά του μήνα.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Συμπεριφορά: επιλέξτε την προεπιλογή AI (Literal, Balanced, Creative), προσθέστε καθολικές οδηγίες προτροπής, ενεργοποιήστε ή απενεργοποιήστε την αυτόματη μετάφραση μετά την αποθήκευση ανάρτησης και διαμορφώστε τη Μνήμη Μετάφρασης.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Η μνήμη μεταφράσεων αποθηκεύει τα αποτελέσματα AI με βάση το περιεχόμενο, το ζεύγος γλωσσών, τον πάροχο και το μοντέλο. Η επεξεργασία μιας ανάρτησης ακυρώνει την καταχώριση cache, ώστε η επόμενη κλήση μετάφρασης να λαμβάνει φρέσκο αποτέλεσμα.','Router Tab'=>'Καρτέλα δρομολογητή','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Βασική γλώσσα: η γλώσσα στην οποία είναι γραμμένο το υπάρχον περιεχόμενό σας. Όλες οι μεταφράσεις παράγονται από αυτήν τη γλώσσα. Η αλλαγή της δεν μετακινεί ή διαγράφει αναρτήσεις.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Δομή URL: λειτουργία προθέματος διαδρομής (example.com/de/) που δεν απαιτεί αλλαγές στον διακομιστή. Λειτουργία υποτομέα (de.example.com) που απαιτεί μια εγγραφή wildcard DNS, ένα πιστοποιητικό SSL wildcard και μια αλλαγή στη διαμόρφωση του διακομιστή — δείτε τον οδηγό ρύθμισης διακομιστή.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Ενεργές γλώσσες: προσθέστε κάθε γλώσσα που θέλετε να υποστηρίξετε. Κάθε γλώσσα λαμβάνει ένα πρόθεμα URL ή υποτομέα και μια ετικέτα hreflang στην ενότητα &lt;head&gt; της σελίδας.','WP site language requirement'=>'Απαιτήσεις γλώσσας ιστότοπου WP','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Η γλώσσα του ιστότοπου WordPress (Ρυθμίσεις → Γενικά → Γλώσσα Ιστότοπου) πρέπει να οριστεί σε μία από τις γλώσσες που χρησιμοποιείτε για το περιεχόμενο — είτε η κύρια γλώσσα περιεχομένου είτε μία από τις δευτερεύουσες γλώσσες. Δεν μπορεί να είναι μια γλώσσα που δεν έχει περιεχόμενο στον ιστότοπο.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Παράδειγμα υποστηριζόμενης διαμόρφωσης: Γλώσσα ιστότοπου WP = CA (Καταλανικά), γλώσσες περιεχομένου = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Παράδειγμα μη υποστηριζόμενης διαμόρφωσης: Γλώσσα ιστότοπου WP = EN (Αγγλικά), γλώσσες περιεχομένου = CA + ES μόνο. Τα Αγγλικά δεν είναι γλώσσα περιεχομένου, οπότε το Lingua Forge δεν μπορεί να αντιστοιχίσει το locale του WP σε οποιαδήποτε ομάδα μετάφρασης.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Όταν η γλώσσα του ιστότοπου WP δεν είναι γλώσσα περιεχομένου: οι ερωτήσεις προϊόντων WooCommerce επιστρέφουν μηδενικά αποτελέσματα σε όλα τα μπλοκ καταλόγου· η ανάθεση εικόνων προϊόντων αποτυγχάνει· όλες οι ερωτήσεις περιεχομένου με φίλτρο γλώσσας σπάνε· ο διακόπτης γλώσσας μπορεί να εμφανίζει μια ψευδή επιλογή γλώσσας που δεν είναι περιεχόμενο. Αν δείτε μια κόκκινη ειδοποίηση διαμόρφωσης στην κορυφή της καρτέλας Router ή System, διορθώστε πρώτα τη γλώσσα του ιστότοπου.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Τοπική διαμόρφωση FSE: σκαλωσιά, μετάφραση και διόρθωση συνδέσμων σε πρότυπα και τμήματα προτύπων του Full Site Editing απευθείας από αυτήν την καρτέλα.','Glossary Tab'=>'Γλωσσάρι','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Καρφιτσώστε όρους που δεν πρέπει να μεταφραστούν ή πρέπει πάντα να αποδίδονται με συγκεκριμένο τρόπο (π.χ. ονόματα εμπορικών σημάτων, ονόματα προϊόντων, ακρωνύμια). Οι περιορισμοί γλωσσάρι εισάγονται σε κάθε αίτημα μετάφρασης AI για όλες τις λειτουργίες: μετάφραση ανάρτησης, μετα-περιγραφή, απόσπασμα και μετάφραση προτύπου FSE.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Προσθέστε έναν όρο ανά γραμμή. Απαιτούνται τόσο ο πηγή όσο και η μεταφρασμένη έκδοση. Το ζεύγος γλωσσών καθορίζει σε ποιες εργασίες μετάφρασης εφαρμόζεται ο περιορισμός.','SEO Tab'=>'Καρτέλα SEO','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Η Lingua Forge είναι μια ολοκληρωμένη λύση SEO για πολλαπλές γλώσσες. Δεν απαιτείται πρόσθετο SEO ή sitemap.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Τι παρέχει το LF: ετικέτες hreflang για κάθε διαμορφωμένη γλώσσα, ετικέτες Open Graph και Twitter Card με og:locale και og:locale:alternate, Schema.org JSON-LD με annotations inLanguage, και ένα ειδικό πολυγλωσσικό sitemap στο /lf-sitemap.xml με εναλλακτικές entries xhtml:link για όλες τις ομάδες μετάφρασης.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Το sitemap ανακοινώνεται αυτόματα στο robots.txt. Όλοι οι μεγάλοι μηχανές αναζήτησης — Google, Bing, Yandex — το ανακαλύπτουν από το robots.txt. Δεν απαιτείται χειροκίνητη υποβολή.','SEO plugins and conflict avoidance:'=>'Plugins SEO και αποφυγή συγκρούσεων:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Εάν έχετε εγκαταστήσει Yoast SEO, Rank Math, All in One SEO ή SEOPress, το Lingua Forge τα ανιχνεύει και προσαρμόζεται για να αποφύγει διπλή έξοδο. Για το hreflang, το LF αναλαμβάνει πλήρως και καταστέλλει την έξοδο του πρόσθετου επειδή αυτά τα πρόσθετα δεν μπορούν να παράγουν σωστό hreflang για μια πολύγλωσση διαμόρφωση δρομολόγησης. Για το Open Graph, το LF προσθέτει μόνο og:locale και og:locale:alternate — τα πολύγλωσσα σήματα που το πρόσθετο δεν μπορεί να παράγει — και αφήνει το βασικό σετ OG στο πρόσθετο. Για το Schema.org, το LF απενεργοποιεί εντελώς τη δική του έξοδο για να αποφύγει συγκρουόμενα γραφήματα JSON-LD.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Η καρτέλα SEO → Συμβατότητα δείχνει την κατάσταση ανίχνευσης σε πραγματικό χρόνο και εξηγεί ακριβώς τι κάνει το LF για κάθε περιοχή λειτουργίας.','SEO Scores'=>'Βαθμολογίες SEO','SEO Score System'=>'Σύστημα βαθμολόγησης SEO','Score computation'=>'Υπολογισμός βαθμολογίας','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Κάθε ανάρτηση βαθμολογείται από 0–100 με έξι κανόνες βάσει μετρικών: τίτλος, μετα-περιγραφή, αριθμός λέξεων, δομή επικεφαλίδων, κάλυψη εναλλακτικών εικόνων και εσωτερικοί σύνδεσμοι. Δέκα βαθμοί απονέμονται πάντα για τον χρόνο ανάγνωσης (μόνο πληροφοριακό). Οι υπόλοιποι 90 βαθμοί κατανέμονται στις άλλες μετρικές με βάρη που διαφέρουν ανά προφίλ περιεχομένου (δείτε παρακάτω).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Κάθε μέτρηση αποδίδει μία από τέσσερις καταστάσεις: ok (πλήρες βάρος), warn (50 % του βάρους), fail (0), ή info (0, χωρίς ποινή). Μία βαθμολογία ≥ 80 είναι πράσινη, 50–79 πορτοκαλί, κάτω από 50 κόκκινη.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Κανόνες βαθμολόγησης τίτλου (όλα τα προφίλ): αποτυχία αν είναι κενός; προειδοποίηση αν είναι λιγότεροι από 10 χαρακτήρες; προειδοποίηση αν είναι μόνο μία λέξη; προειδοποίηση αν είναι μεγαλύτερος από το όριο SERP του προφίλ (60 χαρακτήρες για Blog, 70 για Προϊόν/Σελίδα προορισμού); εντάξει αν είναι τουλάχιστον 10 χαρακτήρες, τουλάχιστον 2 λέξεις, και εντός του ορίου SERP.','Content profiles and weights'=>'Προφίλ περιεχομένου και βάρη','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Τα προφίλ προσαρμόζουν τα όρια και τα βάρη στο είδος του περιεχομένου που αναλύεται. Το προφίλ επιλύεται αυτόματα· μπορείτε να το παρακάμψετε ανά ανάλυση από το αναπτυσσόμενο μενού προφίλ.','Blog / Editorial (default)'=>'Ιστολόγιο / Επιμέλεια (προεπιλογή)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Τίτλος 15 βαθμοί · Μετα-περιγραφή 20 βαθμοί · Αριθμός λέξεων 15 βαθμοί · Επικεφαλίδες 20 βαθμοί · Εικόνες 10 βαθμοί · Συνδέσμοι 10 βαθμοί. Περιορισμός τίτλου SERP 60 χαρακτήρες; μετα-περιγραφή 120–210 χαρακτήρες; προειδοποίηση για κάτω από 300 λέξεις, αποτυχία κάτω από 100; απαιτείται H2; απαιτούνται εσωτερικοί σύνδεσμοι.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Αυτοεντοπισμός για προϊόντα WooCommerce. Τίτλος 20 βαθμοί · Μετα-περιγραφή 30 βαθμοί · Αριθμός λέξεων 15 βαθμοί · Επικεφαλίδες 5 βαθμοί · Εικόνες 20 βαθμοί · Συνδέσεις 0 βαθμοί. Περιορισμός τίτλου SERP 70 χαρακτήρες· προειδοποιήσεις για αριθμό λέξεων κάτω από 80, αποτυχία κάτω από 40; προαιρετικά H2 και εσωτερικοί σύνδεσμοι.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Αυτοεντοπισμός για την στατική αρχική σελίδα· μπορεί να επιλεγεί χειροκίνητα. Τίτλος 20 βαθμοί · Μετα-περιγραφή 30 βαθμοί · Αριθμός λέξεων 15 βαθμοί · Επικεφαλίδες 10 βαθμοί · Εικόνες 15 βαθμοί · Συνδέσεις 0 βαθμοί. Περιορισμός τίτλου SERP 70 χαρακτήρες· προειδοποιήσεις για αριθμό λέξεων κάτω από 150, αποτυχία κάτω από 60; προαιρετικά H2 και εσωτερικοί σύνδεσμοι.','Heading structure rules'=>'Κανόνες δομής επικεφαλίδων','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Ακριβώς ένας H1 απαιτείται. Ο H1 είναι συνήθως ο τίτλος της ανάρτησης που εμφανίζει το θέμα — διαβάζεται από τη ζωντανή σελίδα όταν είναι δυνατόν, και από το περιεχόμενο της ανάρτησης ως εναλλακτική λύση.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Όταν το προφίλ Blog απαιτεί H2 και δεν βρεθεί κανένα, ο αναλυτής ελέγχει πρώτα για υποκεφαλίδες H3 πριν εκδώσει προειδοποίηση. Τα μπλοκ Accordion και Details προεπιλέγουν H3 για τις κεφαλίδες τους; αυτές οι H3 γίνονται αποδεκτές ως έγκυρη δομή και παράγουν αποτέλεσμα ok, όχι προειδοποίηση.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Το σύντομο περιεχόμενο (3 παραγράφοι ή λιγότερο) δεν τιμωρείται ποτέ για απουσία υποκεφαλίδων, ανεξάρτητα από το προφίλ. Μια συνοπτική σελίδα δεν επωφελείται από την επιβολή δομής επικεφαλίδων.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'«Θεωρείστε το H2 ως ισοδύναμο του H1» (Ρυθμίσεις → SEO → Ανάλυση): ενεργοποιήστε αυτό όταν το θέμα σας εμφανίζει τον τίτλο της ανάρτησης μέσα σε H2 αντί για H1. Ο αναλυτής προάγει το πρώτο H2 σε H1 ώστε η βαθμολογία να μην τιμωρείται λανθασμένα.','Score history and badges'=>'Ιστορικό βαθμολογίας και σήματα','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Κάθε φορά που αναλύεται μια ανάρτηση, η βαθμολογία αποθηκεύεται στα μετα-δεδομένα της ανάρτησης. Η στήλη Γλώσσα στη λίστα αναρτήσεων δείχνει μια ετικέτα "SEO N" με χρωματική κωδικοποίηση για κάθε ανάρτηση που έχει αναλυθεί τουλάχιστον μία φορά. Όταν αποθηκεύονται δύο βαθμολογίες, μια ένδειξη διαφοράς (↑N / ↓N) δείχνει την αλλαγή από την προηγούμενη εκτέλεση.','AI Usage & Cache Tab'=>'Καρτέλα Χρήση AI & Cache','Token usage'=>'Χρήση κουπονιών','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Ο πίνακας χρήσης δείχνει την κατανάλωση token AI ανά χαρακτηριστικό (μετάφραση, μετα-περιγραφή, απόσπασμα, πρότυπο FSE, ανάλυση παρτίδας), πάροχο και μοντέλο. Χρησιμοποιήστε τα κουμπιά εύρους ημερομηνιών για φίλτρο σήμερα, τελευταίες 7 ημέρες, τελευταίες 30 ημέρες ή όλο το χρόνο.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Το ημερήσιο όριο (ρυθμίζεται στη Συμπεριφορά → Όρια) παρακολουθείται εδώ. Όταν το όριο φτάσει, οι κλήσεις AI διακόπτονται για το υπόλοιπο της ημέρας. Ο πίνακας δείχνει πόσο από το όριο έχει καταναλωθεί.','Translation caching'=>'Αποθήκευση μεταφράσεων','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Το Lingua Forge χρησιμοποιεί δύο ανεξάρτητα επίπεδα cache για να μειώσει τις περιττές κλήσεις API AI:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Αποθηκεύει τις ακατέργαστες απαντήσεις AI με κλειδί τον περιεχόμενο hash, το ζεύγος γλώσσας, τον πάροχο, το μοντέλο και το προκαθορισμένο. Οι καταχωρίσεις cache ακυρώνονται αυτόματα όταν αλλάζει το περιεχόμενο της πηγής. Διαγράψτε μεμονωμένες καταχωρίσεις ή ολόκληρο το cache από αυτή την καρτέλα.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Αποθηκεύει την πλήρη μεταφρασμένη έξοδο δημοσίευσης ανά περιεχόμενο hash. Επιλογή (ενεργοποιημένο στη Συμπεριφορά). Επιταχύνει τις επαναλαμβανόμενες μεταφράσεις αμετάβλητου περιεχομένου. Διαγράψτε το εδώ όταν θέλετε να αναγκάσετε μια νέα μεταφορά AI ανεξάρτητα από το αν το περιεχόμενο έχει αλλάξει.','Maintenance Tab'=>'Καρτέλα Συντήρησης','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Παρεμβολές γλώσσας: διαχειριστείτε αρχεία υπεροχής .po/.mo για τις συμβολοσειρές UI του Lingua Forge. Χρησιμοποιήστε αυτό αντί να επεξεργάζεστε απευθείας αρχεία πρόσθετου — οι υπεροχές παραμένουν μετά τις ενημερώσεις.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Ανίχνευση σφαλμάτων: ενεργοποιήστε το αρχείο καταγραφής αποσφαλμάτωσης για να καταγράψετε τις προτροπές AI και τις απαντήσεις API σε τοπικό αρχείο. Απενεργοποιήστε μετά την αντιμετώπιση προβλημάτων — η λειτουργία αποσφαλμάτωσης γράφει ένα αρχείο σε κάθε αίτημα AI.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Συμπεριφορά απεγκατάστασης: ελέγχει τι διαγράφεται όταν το πρόσθετο αφαιρείται από τα Πρόσθετα → Εγκατεστημένα πρόσθετα → Διαγραφή. Οι ρυθμίσεις του πρόσθετου και οι cache AI διαγράφονται πάντα. Οι αναθέσεις γλώσσας, οι σχέσεις μετάφρασης, οι μετα-περιγραφές, το γλωσσάριο και η Μνήμη Μετάφρασης διατηρούνται προεπιλεγμένα, ώστε μια τυχαία απεγκατάσταση ή επανεγκατάσταση να μπορεί να συνεχίσει από εκεί που σταμάτησε. Ενεργοποιήστε το "Διαγραφή δεδομένων περιεχομένου κατά την απεγκατάσταση" μόνο όταν αφαιρείτε πλήρως την πολύγλωσση υποστήριξη από τον ιστότοπο — αυτό δεν μπορεί να αναιρεθεί.','System Tab'=>'Καρτέλα Συστήματος','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Διάγνωση μόνο για ανάγνωση της τρέχουσας εγκατάστασης. Δεν αλλάζονται ρυθμίσεις εδώ — χρησιμοποιήστε το για επαλήθευση διαμόρφωσης, εύρεση προβλημάτων και συλλογή πληροφοριών για αναφορές σφαλμάτων.','Sections'=>'Ενότητες','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Έκδοση Lingua Forge, WordPress και PHP; ενεργό θέμα; δομή URL; γλώσσα ιστότοπου WP και κύρια γλώσσα περιεχομένου. Ένδειξη κόκκινου χρώματος δίπλα στη γλώσσα του ιστότοπου WP σημαίνει ότι δεν είναι μία από τις ενεργές γλώσσες περιεχομένου — διορθώστε το στις Ρυθμίσεις → Γενικά πριν από οτιδήποτε άλλο.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Ενεργός πάροχος, διαμορφωμένα κλειδιά, επιλογές επιπέδου μοντέλου, προκαθορισμένο και ημερήσιο όριο.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Επιβεβαιώνει ότι η δομή permalink είναι συμβατή με τη διαδρομή Lingua Forge. Οι απλές και μόνο αριθμητικές δομές δεν υποστηρίζονται.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Λίστα ενεργών πρόσθετων SEO τρίτων. Το Lingua Forge προσαρμόζει την έξοδό του όταν αυτά υπάρχουν — δείτε Ρυθμίσεις → SEO → Συμβατότητα για την ανάλυση ανά χαρακτηριστικό.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Έκδοση WooCommerce, λειτουργία αποθήκευσης παραγγελιών (CPT / HPOS / κοινόχρηστο), και πίνακας κάλυψης μετάφρασης ανά γλώσσα για τις τέσσερις ενσωματωμένες σελίδες WC (Κατάστημα, Καλάθι, Ολοκλήρωση αγοράς, Ο λογαριασμός μου).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Λίστα τύπων δημοσιεύσεων που έχουν δημοσιευμένα posts χωρίς μετα-τιμή _lf_lang. Posts που λείπουν από αυτό το tag είναι αόρατα σε όλα τα φίλτρα γλώσσας. Χρησιμοποιήστε το κουμπί Επιδιόρθωση για να τα ετικετάρετε με τη γλώσσα πηγής, ή Αποκλείστε για να αφαιρέσετε τον τύπο δημοσίευσης από τη δρομολόγηση γλώσσας εντελώς.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Αναδιπλούμενη αποσπασματική καταγραφή όλων των καταχωρίσεων που ανήκουν στο LF στον $wp_rewrite->extra_rules_top. Χρησιμό για διάγνωση 404 ή συγκρούσεις δρομολόγησης μετά την προσθήκη νέας γλώσσας.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Εύκολη αντιγραφή μιας απλής περίληψης συστήματος που καλύπτει όλες τις παραπάνω ενότητες. Επικολλήστε αυτό σε ένα θέμα GitHub ή αίτημα υποστήριξης ώστε να είναι ορατό το πλήρες περιβάλλον με μια ματιά.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Βρήκατε σφάλμα ή απρόβλεπτη συμπεριφορά; Παρακαλώ ανοίξτε ένα θέμα στο GitHub — συμπεριλάβετε το μπλοκ Debug Info παραπάνω και μια σύντομη περιγραφή του τι περιμένατε και τι συνέβη.','Open an issue →'=>'Άνοιγμα θέματος →','Getting started'=>'Εκκίνηση','Server setup (subdomain)'=>'Ρύθμιση διακομιστή (υποτομέας)','Translation workflow'=>'Ροή εργασίας μετάφρασης','Language switcher'=>'Διακόπτης γλώσσας','WP-CLI reference'=>'Αναφορά WP-CLI','Integration API'=>'API Ενσωμάτωσης','Documentation'=>'Τεκμηρίωση','Report an issue on GitHub'=>'Αναφορά προβλήματος στο GitHub','Anthropic (Claude)'=>'Ανθρώπινη (Κλαούντ)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'Πελάτης AI του WordPress (WP 7.0+)','Meta Description, Excerpt Generator'=>'Μετα-περιγραφή, Δημιουργός περίληψης','Translation, Content Generator'=>'Μετάφραση, Δημιουργός Περιεχομένου','Testing…'=>'Δοκιμή…','✓ Connection OK'=>'✓ Σύνδεση ΟΚ','✗ Failed:'=>'✗ Απέτυχε:','No response from provider — check the error log for details.'=>'Δεν υπάρχει απάντηση από τον πάροχο — ελέγξτε το αρχείο σφαλμάτων για λεπτομέρειες.','Network error — could not reach the WordPress AJAX endpoint.'=>'Σφάλμα δικτύου — δεν ήταν δυνατή η πρόσβαση στο σημείο AJAX του WordPress.','Translating a real post with this model…'=>'Μετάφραση ενός πραγματικού δημοσιεύματος με αυτό το μοντέλο…','preset'=>'προεπιλογή','Loading…'=>'Φόρτωση…','Installing…'=>'Εγκατάσταση…','✓ Language installed.'=>'✓ Η γλώσσα εγκαταστάθηκε.','✗ Error:'=>'✗ Σφάλμα:','Creating…'=>'Δημιουργία…','✓ All templates created.'=>'✓ Όλα τα πρότυπα δημιουργήθηκαν.','Some templates could not be created.'=>'Ορισμένα πρότυπα δεν μπόρεσαν να δημιουργηθούν.','Recreating…'=>'Δημιουργία εκ νέου…','✓ All templates recreated.'=>'✓ Όλα τα πρότυπα δημιουργήθηκαν εκ νέου.','Some templates could not be recreated.'=>'Ορισμένα πρότυπα δεν μπόρεσαν να δημιουργηθούν εκ νέου.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Αυτό αντικαθιστά αυτό το πρότυπο με μια φρέσκια αντιγραφή από το ενεργό θέμα, απορρίπτοντας τυχόν προσαρμογές του Site Editor που έγιναν σε αυτό. Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Αυτό αντικαθιστά κάθε πρότυπο με μια φρέσκια αντιγραφή από το ενεργό θέμα, απορρίπτοντας τυχόν προσαρμογές του Site Editor που έγιναν σε αυτά. Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','✓ All parts recreated.'=>'✓ Όλα τα τμήματα δημιουργήθηκαν εκ νέου.','Some parts could not be recreated.'=>'Ορισμένα τμήματα δεν μπόρεσαν να δημιουργηθούν εκ νέου.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Αυτό αντικαθιστά αυτό το τμήμα προτύπου με μια φρέσκια αντιγραφή από το ενεργό θέμα, απορρίπτοντας τυχόν προσαρμογές του Site Editor που έγιναν σε αυτό. Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Αυτό αντικαθιστά κάθε τμήμα προτύπου με μια φρέσκια αντιγραφή από το ενεργό θέμα, απορρίπτοντας τυχόν προσαρμογές του Site Editor που έγιναν σε αυτά. Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','✓ All parts created.'=>'✓ Όλα τα μέρη δημιουργήθηκαν.','Some parts could not be created.'=>'Ορισμένα μέρη δεν μπόρεσαν να δημιουργηθούν.','✓ All translated.'=>'✓ Όλες οι μεταφράσεις ολοκληρώθηκαν.','Some translations failed.'=>'Ορισμένες μεταφράσεις απέτυχαν.','Review carefully — links and slugs not updated.'=>'Ελέγξτε προσεκτικά — οι σύνδεσμοι και τα slugs δεν ενημερώθηκαν.','Fixing…'=>'Επιδιόρθωση…','✓ Links fixed.'=>'✓ Οι σύνδεσμοι διορθώθηκαν.','Some link fixes failed.'=>'Ορισμένες διορθώσεις συνδέσμων απέτυχαν.','✓ Parts fixed.'=>'✓ Τα μέρη διορθώθηκαν.','Some part fixes failed.'=>'Ορισμένες διορθώσεις μερών απέτυχαν.','✓ Nav refs fixed.'=>'✓ Οι αναφορές πλοήγησης διορθώθηκαν.','Some nav ref fixes failed.'=>'Ορισμένες διορθώσεις αναφορών πλοήγησης απέτυχαν.','✓ Pattern translated.'=>'✓ Το μοτίβο μεταφράστηκε.','Pattern translation failed.'=>'Αποτυχία μετάφρασης μοτίβου.','Hide'=>'Απόκρυψη','Re-create all templates'=>'Δημιουργία όλων των προτύπων εκ νέου','Re-create all parts'=>'Δημιουργία όλων των τμημάτων εκ νέου','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Αυτό εκτελεί Δημιουργία όλων των προτύπων εκ νέου, Δημιουργία όλων των τμημάτων εκ νέου, Μετάφραση όλων, Επιδιόρθωση όλων των τμημάτων και Επιδιόρθωση όλων των συνδέσμων για καθεμία από τις {total} ενεργές γλώσσες σας, η μία γλώσσα κάθε φορά. Αντικαθιστά τα υπάρχοντα πρότυπα και τμήματα με φρέσκιες αντιγραφές από το ενεργό θέμα (απορρίπτοντας προσαρμογές του Site Editor) και επαναμεταφράζει το περιεχόμενο — κανένα από αυτά δεν μπορεί να αναιρεθεί. Η Μετάφραση όλων κάνει πραγματικές κλήσεις AI API για κάθε πρότυπο και τμήμα, που ενδέχεται να χρειαστεί χρόνο και ενδέχεται να προκαλέσει κόστος ανάλογα με τον πάροχό σας. Συνέχεια;','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Αυτό εκτελεί Δημιουργία όλων των προτύπων εκ νέου, Μετάφραση όλων, Επιδιόρθωση όλων των τμημάτων και Επιδιόρθωση όλων των συνδέσμων για καθεμία από τις {total} ενεργές γλώσσες σας, η μία γλώσσα κάθε φορά — τα τμήματα προτύπων (κεφαλίδες, υποσέλιδα κ.λπ.) παραμένουν ανεπηρέαστα. Αντικαθιστά τα υπάρχοντα πρότυπα με φρέσκιες αντιγραφές από το ενεργό θέμα (απορρίπτοντας προσαρμογές του Site Editor) και επαναμεταφράζει το περιεχόμενο — κανένα από αυτά δεν μπορεί να αναιρεθεί. Η Μετάφραση όλων κάνει πραγματικές κλήσεις AI API για κάθε πρότυπο, που ενδέχεται να χρειαστεί χρόνο και ενδέχεται να προκαλέσει κόστος ανάλογα με τον πάροχό σας. Συνέχεια;','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Αυτό εκτελεί Δημιουργία όλων των τμημάτων εκ νέου (κεφαλίδες, υποσέλιδα και κάθε άλλο τμήμα προτύπου) για καθεμία από τις {total} ενεργές γλώσσες σας, η μία γλώσσα κάθε φορά. Αντικαθιστά τα υπάρχοντα τμήματα προτύπων με φρέσκιες αντιγραφές από το ενεργό θέμα, απορρίπτοντας τυχόν προσαρμογές του Site Editor που έγιναν σε αυτά. Αυτό δεν μπορεί να αναιρεθεί. Συνέχεια;','Starting…'=>'Εκκίνηση…','Processing {lang} ({index} of {total}) — {step}…'=>'Επεξεργασία {lang} ({index} από {total}) — {step}…','Cancelled.'=>'Ακυρώθηκε.','{done} of {total} languages processed.'=>'{done} από {total} γλώσσες επεξεργάστηκαν.','⚠ Done with issues.'=>'⚠ Ολοκληρώθηκε με προβλήματα.','✓ All {total} languages processed.'=>'✓ Όλες οι {total} γλώσσες επεξεργάστηκαν.','Built-in preset instructions:'=>'Ενσωματωμένες προεπιλεγμένες οδηγίες:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Δεν υπάρχουν ενσωματωμένες οδηγίες — κάθε λειτουργία AI χρησιμοποιεί τις δικές της ρυθμίσεις. Συμπληρώστε το πεδίο Οδηγίες προσαρμοσμένου προτροπής παρακάτω για να προσθέσετε τους δικούς σας κανόνες σε όλο τον ιστότοπο.','Modified'=>'Τροποποιήθηκε','edit'=>'επεξεργασία','No published posts found for the selected filters.'=>'Δεν βρέθηκαν δημοσιευμένες αναρτήσεις για τα επιλεγμένα φίλτρα.','Just now'=>'Μόλις τώρα','Score'=>'Βαθμολογία','Source title'=>'Τίτλος πηγής','Multilingual SEO overview'=>'Επισκόπηση πολυγλωσσικού SEO','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Οι βαθμολογίες είναι ένα σήμα, όχι ένα τελικό αποτέλεσμα. Ορισμένο περιεχόμενο έχει δομικούς περιορισμούς — πολύ σύντομες σελίδες, σελίδες προορισμού με λίγο κείμενο σώματος ή σελίδες που έχουν σκοπό την πλοήγηση και όχι την πληροφόρηση μπορεί να βαθμολογούνται χαμηλότερα από τη φύση τους. Χρησιμοποιήστε αυτήν την επισκόπηση για να εντοπίσετε πραγματικά κενά ισοτιμίας μεταξύ γλωσσών, όχι για να κυνηγήσετε έναν αριθμό.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Αυτή είναι μια σελίδα συστήματος WooCommerce (Κατάστημα, Καλάθι, Ολοκλήρωση αγοράς, κ.λπ.). Το περιεχόμενό της διαχειρίζεται το WooCommerce — η βαθμολογία αντικατοπτρίζει μόνο δομικά σήματα, όχι περιεχόμενο SEO που επεξεργάζεται ο χρήστης.','Settings'=>'Ρυθμίσεις','You do not have permission to manage these settings.'=>'Δεν έχετε άδεια να διαχειριστείτε αυτές τις ρυθμίσεις.','Lingua Forge — Settings'=>'Lingua Forge — Ρυθμίσεις','Settings saved.'=>'Οι ρυθμίσεις αποθηκεύτηκαν.','Save Settings'=>'Αποθήκευση ρυθμίσεων','Standard'=>'Τυπικό','Technical / Scientific'=>'Τεχνικό / Επιστημονικό','Legal / Compliance'=>'Νομικό / Συμμόρφωση','Creative / Marketing'=>'Δημιουργικό / Μάρκετινγκ','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Στατιστικά Χρήσης AI','Lingua Forge AI Usage Statistics'=>'Στατιστικές Χρήσης Lingua Forge AI','Date'=>'Ημερομηνία','Request count'=>'Αριθμός αιτημάτων','Full Article'=>'Ολόκληρο το άρθρο','Introduction only'=>'Μόνο εισαγωγή','Structured Outline'=>'Δομημένη περίληψη','Generate Content'=>'Παραγωγή περιεχομένου','Hints'=>'Υποδείξεις','Key points, ideas, or structure to build from…'=>'Βασικά σημεία, ιδέες ή δομή από την οποία να χτιστεί…','Tone'=>'Τόνος','Output'=>'Αποτέλεσμα','Generate Excerpt'=>'Δημιουργία αποσπάσματος','Generate Meta Description'=>'Δημιουργία μετα-περιγραφής','Translate Content'=>'Μετάφραση περιεχομένου','Mode'=>'Λειτουργία','Full post'=>'Πλήρες ποστ','Translate chunk'=>'Μεταφράστε το τμήμα','Target Language'=>'Γλώσσα προορισμού','Text to translate'=>'Κείμενο προς μετάφραση','Paste a footnote, sentence, or any snippet here…'=>'Επικολλήστε μια υποσημείωση, πρόταση ή οποιοδήποτε απόσπασμα εδώ…','Also generate meta description'=>'Επίσης δημιουργήστε μετα-περιγραφή','Translated Labels'=>'Μεταφρασμένες Ετικέτες','Attribute label displayed in this language. Leave empty to use the default label.'=>'Ετικέτα χαρακτηριστικού που εμφανίζεται σε αυτή τη γλώσσα. Αφήστε κενό για να χρησιμοποιήσετε την προεπιλεγμένη ετικέτα.','Translate all labels (AI)'=>'Μετάφραση όλων των ετικετών (AI)','Insufficient permissions.'=>'Ανεπαρκή δικαιώματα.','All labels already translated.'=>'Όλες οι ετικέτες έχουν ήδη μεταφραστεί.','%d label(s) translated.'=>'%d ετικετα(ες) μεταφράστηκαν.','Translation failed. Check the browser console.'=>'Η μετάφραση απέτυχε. Ελέγξτε την κονσόλα του προγράμματος περιήγησης.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Δεν είναι δυνατή η εγγραφή στον προϊόν %1$d: είναι μεταφρασμένη έκδοση (γλώσσα: %2$s)%3$s. Τα λειτουργικά δεδομένα (τιμή, απόθεμα, SKU, διαστάσεις) πρέπει να ενημερώνονται στο αρχικό προϊόν. Εντοπίστε το ID του αρχικού προϊόντος μέσω: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Μεταφρασμένα ονόματα','Name displayed in this language. Leave empty to use the source name.'=>'Όνομα που εμφανίζεται σε αυτή τη γλώσσα. Αφήστε κενό για να χρησιμοποιήσετε το αρχικό όνομα.','Translate all tags (AI)'=>'Μετάφραση όλων των ετικετών (AI)','Translate all categories (AI)'=>'Μετάφραση όλων των κατηγοριών (AI)','Translate all %s terms (AI)'=>'Μετάφραση όλων των όρων %s (AI)','Translate all terms (AI)'=>'Μετάφραση όλων των όρων (AI)','Invalid taxonomy.'=>'Μη έγκυρη ταξινομία.','No terms found.'=>'Δεν βρέθηκαν όροι.','%d term(s) translated.'=>'%d όρος(οι) μεταφράστηκαν.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d ήδη μεταφρασμένο — <a href="#" class="lf-force-translate">αναγκαστική επανεξέταση</a>','%1$d translated, %2$d skipped.'=>'%1$d μεταφράστηκαν, %2$d παραλείφθηκαν.','Order placed in language: %s'=>'Παραγγελία τοποθετήθηκε στη γλώσσα: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Μη έγκυρο κλειδί API — ελέγξτε διπλά το κλειδί που εισάγετε στις ρυθμίσεις παρόχου AI.','Payment required — your account has no remaining credits.'=>'Απαιτείται πληρωμή — ο λογαριασμός σας δεν έχει υπόλοιπο πιστώσεων.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Απαγορεύεται η πρόσβαση — ο λογαριασμός σας ενδέχεται να ανασταλεί ή το κλειδί να στερείται των απαιτούμενων δικαιωμάτων.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Περιορισμός ρυθμού — υπερβολικά πολλά αιτήματα προς τον πάροχο· περιμένετε λίγο και δοκιμάστε ξανά.','Provider service temporarily unavailable — try again in a moment.'=>'Η υπηρεσία του παρόχου είναι προσωρινά μη διαθέσιμη — δοκιμάστε ξανά σε λίγο.','Provider error (HTTP %1$d): %2$s'=>'Σφάλμα παρόχου (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Απροσδόκητο σφάλμα παρόχου (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Δεν έχει ρυθμιστεί κλειδί API — εισάγετε το κλειδί σας στις ρυθμίσεις παρόχου AI.','Network error — could not reach the provider: %s'=>'Σφάλμα δικτύου — δεν ήταν δυνατή η επικοινωνία με τον πάροχο: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Δεν απομένουν πιστώσεις — φορτώστε ξανά τον λογαριασμό OpenAI στη διεύθυνση platform.openai.com/account/billing.','WordPress AI Client requires WordPress 7.0 or later.'=>'Ο Πελάτης AI του WordPress απαιτεί WordPress 7.0 ή νεότερο.','No user message found in the message array.'=>'Δεν βρέθηκε μήνυμα χρήστη στη σειρά μηνυμάτων.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Δεν υπάρχει διαθέσιμο μοντέλο δημιουργίας κειμένου. Διαμορφώστε έναν πάροχο AI στις Ρυθμίσεις → Συνδετήρες.','Too many AI requests. Please retry in %d seconds.'=>'Πάρα πολλά αιτήματα AI. Παρακαλώ δοκιμάστε ξανά σε %d δευτερόλεπτα.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Η ημερήσια ποσόστωση AI έχει φτάσει (%1$d αιτήματα). Επαναφέρεται στις %2$s UTC.','View Lingua Forge details'=>'Προβολή λεπτομερειών Lingua Forge','View details'=>'Προβολή λεπτομερειών','Visit plugin site'=>'Επισκεφθείτε τον ιστότοπο του πρόσθετου','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Ενημέρωση Lingua Forge αποκλεισμένη: ο διακομιστής φιλοξενίας "%s" δεν είναι στη λίστα επιτρεπτών.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Η ενημέρωση Lingua Forge αποκλεισμένη: το SHA-256 του κατεβασμένου πακέτου δεν ταιριάζει με το μανιφέστο. Το αρχείο ενδέχεται να έχει παραποιηθεί.','Exclude from navigation menus'=>'Αποκλεισμός από μενού πλοήγησης','Apply to all language versions'=>'Εφαρμογή σε όλες τις εκδόσεις γλώσσας','Lang'=>'Γλώσσα','Also mirrored to: %s'=>'Επίσης αντηχεί σε: %s','Filter by language'=>'Φίλτρο κατά γλώσσα','All languages'=>'Όλες οι γλώσσες','Noindex (hide this language version from search engines)'=>'Noindex (απόκρυψη αυτής της έκδοσης γλώσσας από τις μηχανές αναζήτησης)','%d language not yet linked'=>'%d γλώσσα δεν έχει ακόμη συσχετιστεί' . "\0" . '%d γλώσσες δεν έχουν ακόμη συσχετιστεί','This is the source page. Footnotes are edited directly in the block editor.'=>'Αυτή είναι η αρχική σελίδα. Οι υποσημειώσεις επεξεργάζονται απευθείας στον επεξεργαστή μπλοκ.','No source page linked yet.'=>'Δεν έχει ακόμη συσχετιστεί σελίδα πηγής.','The source page has no footnotes.'=>'Η σελίδα πηγής δεν έχει υποσημειώσεις.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Αυτές οι υποσημειώσεις προέρχονται από τη σελίδα πηγής και εμφανίζονται εδώ μόνο για αναφορά. Προσθέστε τες σε αυτή τη σελίδα χρησιμοποιώντας τον επεξεργαστή μπλοκ.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d τοπικοποιημένο(α) πρότυπο(α) από το θέμα &#8220;%2$s&#8221;» διατηρούνται στη βάση δεδομένων, αλλά είναι επί του παρόντος ανενεργά. Θα ενεργοποιηθούν ξανά αν ενεργοποιήσετε ξανά αυτό το θέμα. Για να μεταφέρετε τις μεταφράσεις σας στο νέο θέμα, αναγεννήστε τες μέσω <strong>Ρυθμίσεις → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Σάρωση δημοσιεύσεων για εικόνες εξωφύλλου που λείπουν ή δεν είναι συγχρονισμένες…','Re-scanning…'=>'Επανεξέταση…','Scan failed: '=>'Η σάρωση απέτυχε: ','unknown error'=>'άγνωστο σφάλμα','Scan request failed. Please try again.'=>'Απέτυχε το αίτημα σάρωσης. Παρακαλώ δοκιμάστε ξανά.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Δεν βρέθηκαν αναρτήσεις <strong>{lang}</strong>. Βεβαιωθείτε ότι όλες οι μεταφρασμένες αναρτήσεις έχουν ορισμένο το μετα-περιεχόμενο Γλώσσα σε <strong>{lang}</strong> στο πλαίσιο μετα-γλώσσας.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Όλες οι <strong>{lang}</strong> εικόνες προφίλ είναι ήδη συγχρονισμένες με τη πηγή τους. Σάρωση <strong>{scanned}</strong> ανάρτηση(εις).','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Βρέθηκαν <strong>{n}</strong> δημοσίευση(σεις) που λείπουν ή δεν είναι συγχρονισμένες με την εικόνα προβολής τους, από <strong>{scanned}</strong> που σαρώθηκαν για <strong>{lang}</strong>.','Post'=>'Ανάρτηση','Current'=>'Τρέχον','Source (EN)'=>'Όρος πηγής','None'=>'Κανένας','Copy from source'=>'Αντιγραφή από την πηγή','Copying…'=>'Αντιγραφή…','✅ Copied'=>'✅ Αντιγράφηκε','❌ Failed'=>'❌ Απέτυχε','Done — {done} of {total} post(s) fixed.'=>'Ολοκληρώθηκε — διορθώθηκαν {done} από {total} αναρτήσεις.','Fixing {n} / {total}…'=>'Διόρθωση {n} / {total}…','Fix Featured Images'=>'Διόρθωση Εικόνων Προβολής','Featured Image Fixer'=>'Διορθωτής Εικόνας Προβολής','Fix All'=>'Διόρθωσε Όλα','Re-scan'=>'Επανασάρωση','Scanning posts for broken language links…'=>'Ανίχνευση αναρτήσεων για σπασμένους συνδέσμους γλώσσας…','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Δεν βρέθηκαν σπασμένοι σύνδεσμοι ή ασυμβατότητες προτύπων για <strong>{lang}</strong>. Σάρωση <strong>{scanned}</strong> ανάρτησης(ων) και σελίδων — όλες οι έλεγχοι πέρασαν. Οι σύνδεσμοι τμημάτων προτύπου (κεφαλίδα, υποσέλιδο, πλαϊνή γραμμή) δεν περιλαμβάνονται εδώ — χρησιμοποιήστε το κουμπί Διόρθωση Τμημάτων Προτύπου για να ελέγξετε αυτά ξεχωριστά.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> αυτόματοι διορθώσιμοι σύνδεσμοι','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> σύνδεσμοι που χρειάζονται χειροκίνητο έλεγχο','and'=>'και','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Βρέθηκαν {parts} σε <strong>{total}</strong> από <strong>{scanned}</strong> ανιχνευμένες αναρτήσεις για <strong>{lang}</strong>.','link(s)'=>'σύνδεσμος(οι)','Fix'=>'Διόρθωση','✅ Fixed ({n})'=>'✅ Διορθώθηκε ({n})','⚠ No changes — re-scan?'=>'⚠ Χωρίς αλλαγές — επανεξέταση;','⚠ No changes'=>'⚠ Χωρίς αλλαγές','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} δεν είχαν αντικαταστάσιους συνδέσμους — επανεξέταση για διερεύνηση)','URL could not be mapped to a post — check the link target exists'=>'Ο σύνδεσμος URL δεν μπόρεσε να αντιστοιχιστεί σε ανάρτηση — ελέγξτε αν υπάρχει ο στόχος του συνδέσμου','No {lang} translation registered (TRID missing)'=>'Δεν έχει καταχωρηθεί μετάφραση {lang} (TRID λείπει)','Translation found but permalink could not be generated'=>'Βρέθηκε μετάφραση, αλλά ο σύνδεσμος μόνιμης αναφοράς δεν μπόρεσε να δημιουργηθεί','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> παρωχημένη διαδρομή(ες)','📍 Stale path (page moved)'=>'📍 Παλαιά διαδρομή (η σελίδα μετακινήθηκε)','{n} stale path(s)'=>'{n} παρωχημένη διαδρομή(ες)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> πρόβλημα(τα) προτύπου','📄 Wrong template'=>'📄 Λάθος πρότυπο','Expected: {expected}'=>'Αναμενόμενο: {expected}','Current: {current}'=>'Τρέχον: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Το πρότυπο "{expected}" δεν υπάρχει — δημιουργήστε το πρώτα στον Επεξεργαστή Ιστοσελίδων.','Fix Template'=>'Διόρθωση Προτύπου','✅ Template fixed'=>'✅ Το πρότυπο διορθώθηκε','Internal Link Fixer'=>'Εργαλείο Διόρθωσης Εσωτερικών Συνδέσμων','Language Switcher'=>'Εναλλαγή Γλώσσας','Displays the Lingua Forge language switcher.'=>'Εμφανίζε